function getLocalizedCatalogItem(category, key, defaultName, defaultDesc) {
  const lang = state.currentLanguage || 'en';
  if (lang === 'en') return { name: defaultName, desc: defaultDesc };
  const cat = LOCALIZED_CATALOG_DATA[category];
  if (cat) {
    if (cat[key] && cat[key][lang]) return cat[key][lang];
    const normKey = (key || '').toLowerCase().replace(/[-_]/g, '');
    for (const k of Object.keys(cat)) {
      if (k.toLowerCase().replace(/[-_]/g, '') === normKey && cat[k][lang]) {
        return cat[k][lang];
      }
    }
  }
  return { name: defaultName, desc: defaultDesc };
}

