function setLanguage(lang) {
  if (!I18N_TRANSLATIONS[lang]) lang = 'en';
  state.currentLanguage = lang;
  localStorage.setItem('solace_preferred_lang', lang);
  document.documentElement.setAttribute('lang', lang);

  // Sync active states on all language switcher button pills across the app
  document.querySelectorAll('.lang-pill-btn').forEach(btn => {
    if (btn.getAttribute('data-lang') === lang) {
      btn.classList.add('active');
    } else {
      btn.classList.remove('active');
    }
  });

  const langNames = { en: "English (EN)", zh: "简体中文 (ZH)", ms: "Bahasa Melayu", ta: "தமிழ் (Tamil)" };
  const labelEl = document.getElementById('account-current-lang-label');
  if (labelEl) labelEl.textContent = langNames[lang] || "English (EN)";

  const dict = I18N_TRANSLATIONS[lang] || I18N_TRANSLATIONS.en;

  // Update text nodes with data-i18n
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (dict[key]) el.textContent = dict[key];
  });

  // Update placeholders with data-i18n-placeholder
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.getAttribute('data-i18n-placeholder');
    if (dict[key]) el.setAttribute('placeholder', dict[key]);
  });

  // Update titles with data-i18n-title
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    const key = el.getAttribute('data-i18n-title');
    if (dict[key]) el.setAttribute('title', dict[key]);
  });

  // Update aria-labels with data-i18n-aria. A screen reader user hears these
  // instead of the visible text, so leaving them English would mean the app
  // reads out in English no matter which language is selected.
  document.querySelectorAll('[data-i18n-aria]').forEach(el => {
    const key = el.getAttribute('data-i18n-aria');
    if (dict[key]) el.setAttribute('aria-label', dict[key]);
  });

  // Rewrite the opening greeting only. Everything else in the feed is either
  // the family's own words or a backend reply, and must be left exactly as it
  // was said.
  document.querySelectorAll('[data-greeting-bubble]').forEach(el => {
    const fresh = buildGreeting();
    if (fresh) el.textContent = fresh;
    if (typeof chatHistory !== 'undefined' && chatHistory.length &&
        chatHistory[0] && chatHistory[0].role === 'assistant') {
      chatHistory[0].content = fresh;
    }
  });

  // Dynamically re-render active screens to apply full localized terms
  updateHubGreeting();
  if (typeof renderQuickChips === 'function') renderQuickChips();
  if (typeof loadTermsContent === 'function') loadTermsContent();
  if (state.currentScreen === '2') {
    renderDashboardSaved();
  } else if (state.currentScreen === '4') {
    renderPlannerSelectors();
    recalculatePlannerPrice();
  } else if (state.currentScreen === '5') {
    populatePDFQuote();
  }
}


// Attach listener to all language buttons on DOMContentLoaded
document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('.lang-pill-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      const chosen = btn.getAttribute('data-lang');
      if (chosen) setLanguage(chosen);
    });
  });
  setLanguage(state.currentLanguage || 'en');
});


