function updateClock() {
  const now = new Date();
  let hours = now.getHours();
  let minutes = now.getMinutes();
  hours = hours < 10 ? '0' + hours : hours;
  minutes = minutes < 10 ? '0' + minutes : minutes;
  clockEl.textContent = `${hours}:${minutes}`;
}
setInterval(updateClock, 60000);
updateClock();
loadTermsContent();

function updateHeaderQuoteBadge() {
  if (headerQuoteBadge) {
    if (!state.quoteId) {
      // A fresh session gets its own id. Reusing a seed draft's id (9812A) made
      // saving produce a second card with the same ID as the active session.
      state.quoteId = generateUniqueQuoteId();
    }
    headerQuoteBadge.textContent = state.quoteId;
    headerQuoteBadge.classList.remove('hidden');
  }
}

// ==========================================
// SCREEN NAVIGATION SYSTEM 
// ==========================================
function navigateTo(screenNum) {
  closeTermsModal();
  state.currentScreen = screenNum;

  const screens = [
    { num: '1', el: screen1 },
    { num: '2', el: screen2 },
    { num: '3', el: screen3 },
    { num: '4', el: screen4 },
    { num: '5', el: screen5 },
    { num: '6', el: screen6 }
  ];

  if (screenNum === '1') {
    appHeader.classList.add('hidden');
    appNav.classList.add('hidden');
  } else {
    appHeader.classList.remove('hidden');
    appNav.classList.remove('hidden');
    updateHeaderQuoteBadge();
    updateNavSelection(screenNum);
  }

  screens.forEach(screen => {
    if (screen.el) {
      if (screen.num === screenNum) {
        screen.el.classList.add('active');
      } else {
        screen.el.classList.remove('active');
      }
    }
  });

  if (screenNum === '2') {
    updateHubGreeting();
    renderDashboardSaved();
    updateObituaryDraft();
  } else if (screenNum === '3') {
    if (chatHistory.length === 0) {
      resetAndStartChat();
    }
  } else if (screenNum === '4') {
    renderPlannerSelectors();
    recalculatePlannerPrice();
  } else if (screenNum === '5') {
    populatePDFQuote();
    resizeSignatureCanvas();
  } else if (screenNum === '6') {
    updateAccountModalDisplay();
  }
}

