function updateNavSelection(screenNum) {
  const tabs = appNav.querySelectorAll('[data-tab]');
  tabs.forEach(tab => {
    const tabName = tab.getAttribute('data-tab');
    let isSelected = false;

    if (tabName === 'hub' && screenNum === '2') isSelected = true;
    if (tabName === 'chat' && screenNum === '3') isSelected = true;
    if (tabName === 'planner' && screenNum === '4') isSelected = true;
    if (tabName === 'esign' && screenNum === '5') isSelected = true;
    if (tabName === 'account' && screenNum === '6') isSelected = true;

    // Colour alone was too subtle to read at a glance. The active tab now also
    // carries a soft filled pill and a dot marker, so the current section is
    // obvious without comparing shades.
    if (isSelected) {
      tab.classList.remove('text-textMuted', 'hover:text-primary');
      tab.classList.add('text-primary', 'nav-tab-active');
    } else {
      tab.classList.remove('text-primary', 'nav-tab-active');
      tab.classList.add('text-textMuted', 'hover:text-primary');
    }
  });
}

