function showFamilyLoadingGate(onComplete) {
  const overlay = document.getElementById('family-loading-overlay');
  const titleEl = document.getElementById('family-loading-title');
  const subEl = document.getElementById('family-loading-sub');
  const fillEl = overlay ? overlay.querySelector('.family-loading-bar-fill') : null;

  if (!overlay) {
    if (typeof onComplete === 'function') {
      try { onComplete(); } catch (err) { console.error('Error in onComplete:', err); }
    }
    return;
  }

  const familyName = state.user && state.user.name && state.user.name !== 'Guest Family' ? state.user.name : null;

  // Reset initial state
  if (titleEl) {
    titleEl.textContent = 'Take a quiet breath...';
    titleEl.style.opacity = '1';
    titleEl.style.transform = 'translateY(0)';
  }
  if (subEl) {
    subEl.textContent = familyName ? `Welcoming ${familyName} \u2022 Solace Care` : 'Solace Dignity Care \u2022 Singapore';
  }
  if (fillEl) {
    fillEl.style.transition = 'none';
    fillEl.style.width = '0%';
  }

  // Reveal overlay
  overlay.classList.add('is-visible');
  overlay.setAttribute('aria-hidden', 'false');

  // Trigger progress bar
  requestAnimationFrame(() => {
    if (fillEl) {
      fillEl.style.transition = 'width 1400ms cubic-bezier(0.16, 1, 0.3, 1)';
      fillEl.style.width = '100%';
    }
  });

  // Phase 2 text transition (fade out completely first, then replace and fade in)
  setTimeout(() => {
    if (titleEl) {
      titleEl.style.opacity = '0';
      titleEl.style.transform = 'translateY(-4px)';
      setTimeout(() => {
        titleEl.textContent = 'Opening your family care sanctuary...';
        titleEl.style.transform = 'translateY(4px)';
        requestAnimationFrame(() => {
          titleEl.style.opacity = '1';
          titleEl.style.transform = 'translateY(0)';
        });
      }, 200);
    }
  }, 750);

  let isDismissed = false;
  const dismissOverlay = () => {
    if (isDismissed) return;
    isDismissed = true;
    overlay.classList.remove('is-visible');
    overlay.setAttribute('aria-hidden', 'true');
  };

  // Complete and navigate with guaranteed dismiss
  setTimeout(() => {
    try {
      if (typeof onComplete === 'function') {
        onComplete();
      }
    } catch (err) {
      console.error('Error during family loading navigation:', err);
    } finally {
      setTimeout(dismissOverlay, 250);
    }
  }, 1500);

  // Hard safety watchdog timer: unconditionally dismisses overlay after 2.5s
  setTimeout(dismissOverlay, 2500);
}

