async function performLogout() {
  const token = getSessionToken();
  if (token) {
    try {
      fetch(`${API_BASE}/api/auth/logout`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}` }
      }).catch(() => {});
    } catch (e) {}
    try {
      sessionStorage.removeItem(SESSION_TOKEN_KEY);
    } catch (e) {}
  }

  // Clear state and return to login without deleting localStorage
  state.user = {
    id: null,
    username: '',
    contact: '',
    name: 'Jane Doe',
    email: '',
    phone: '',
    isGuest: true
  };
  resetArrangementState();

  if (accountModal) accountModal.classList.add('opacity-0', 'pointer-events-none');
  showAuthView('login');
  navigateTo('1');
}

async function checkAndRestoreSession() {
  const token = getSessionToken();
  if (!token) {
    loadPersistedDrafts();
    loadWorkInProgress();
    updateHeaderAccountDisplay();
    return;
  }

  try {
    const resp = await fetch(`${API_BASE}/api/auth/me`, {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    if (resp.ok) {
      const user = await resp.json();
      state.user = {
        id: user.user_id,
        username: user.username,
        name: user.full_name,
        contact: user.phone || user.email || '',
        email: user.email || '',
        phone: user.phone || '',
        isGuest: false
      };
      migrateLegacyDrafts(user.user_id);
      loadPersistedDrafts();
      loadWorkInProgress();
      updateHeaderAccountDisplay();
      syncFromCloud();
      if (state.currentScreen === '1') {
        navigateTo('2');
      }
    } else {
      sessionStorage.removeItem(SESSION_TOKEN_KEY);
      state.user = { id: null, username: '', contact: '', name: 'Jane Doe', email: '', phone: '', isGuest: true };
      loadPersistedDrafts();
      loadWorkInProgress();
      updateHeaderAccountDisplay();
    }
  } catch (err) {
    console.warn('Session check network error:', err);
    loadPersistedDrafts();
    loadWorkInProgress();
    updateHeaderAccountDisplay();
  }
}

async function loadTermsContent() {
  try {
    const curLang = state.currentLanguage || 'en';
    const resp = await fetch(`${API_BASE}/api/legal/terms?lang=${encodeURIComponent(curLang)}`);
    if (resp.ok) {
      const data = await resp.json();
      if (data && data.sections && data.sections.length) {
        const html = data.sections.map(s => `
          <div>
            <h4 class="font-serif font-bold text-[14.5px] text-textDark mb-1">${escapeHtml(s.heading)}</h4>
            <p class="text-textDark/85 whitespace-pre-line">${escapeHtml(s.body)}</p>
          </div>
        `).join('');
        if (consentTermsContent) consentTermsContent.innerHTML = html;
        const modalBody = document.getElementById('terms-modal-body');
        if (modalBody) modalBody.innerHTML = html;
      }
    }
  } catch (e) {
    console.warn('Could not fetch dynamic terms:', e);
  }
}

// Password show/hide toggle helper
function setupPasswordToggle(btn, input) {
  if (!btn || !input) return;
  btn.addEventListener('click', () => {
    const isPw = input.type === 'password';
    input.type = isPw ? 'text' : 'password';
    const showIcon = btn.querySelector('.eye-icon-show');
    const hideIcon = btn.querySelector('.eye-icon-hide');
    if (showIcon) showIcon.classList.toggle('hidden', isPw);
    if (hideIcon) hideIcon.classList.toggle('hidden', !isPw);
    btn.setAttribute('aria-label', isPw ? 'Hide password' : 'Show password');
  });
}

setupPasswordToggle(btnToggleLoginPassword, loginPasswordInput);
