async function handleLoginSubmit() {
  clearAuthErrors();
  const username = (loginUsernameInput && loginUsernameInput.value.trim()) || '';
  const password = (loginPasswordInput && loginPasswordInput.value) || '';

  let hasError = false;
  if (!username) {
    if (loginUsernameError) {
      loginUsernameError.textContent = 'Please enter your username.';
      loginUsernameError.classList.remove('hidden');
    }
    hasError = true;
  }
  if (!password) {
    if (loginPasswordError) {
      loginPasswordError.textContent = 'Please enter your password.';
      loginPasswordError.classList.remove('hidden');
    }
    hasError = true;
  }
  if (hasError) return;

  // Show button spinner & disable
  btnSubmitLogin.disabled = true;
  const btnText = btnSubmitLogin.querySelector('.btn-text');
  const btnArrow = btnSubmitLogin.querySelector('.btn-arrow');
  const btnSpinner = btnSubmitLogin.querySelector('.btn-spinner');
  if (btnText) btnText.textContent = 'Signing in…';
  if (btnArrow) btnArrow.classList.add('hidden');
  if (btnSpinner) btnSpinner.classList.remove('hidden');

  try {
    const resp = await fetch(`${API_BASE}/api/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, password })
    });

    if (resp.ok) {
      const data = await resp.json();
      sessionStorage.setItem(SESSION_TOKEN_KEY, data.token);

      // Reset state to defaults before loading user data to prevent cross-session leakage
      resetArrangementState();
      state.user = {
        id: data.user_id,
        username: data.username,
        name: data.full_name,
        contact: data.phone || data.email || '',
        email: data.email || '',
        phone: data.phone || '',
        isGuest: false
      };

      migrateLegacyDrafts(data.user_id);
      loadPersistedDrafts();
      loadWorkInProgress();
      updateHeaderAccountDisplay();
      await syncFromCloud();

      showFamilyLoadingGate(() => {
        navigateTo('2');
      });
    } else {
      const errData = await resp.json().catch(() => ({}));
      const msg = errData.detail || 'Username or password is incorrect.';
      if (loginGeneralError) {
        loginGeneralError.textContent = msg;
        loginGeneralError.classList.remove('hidden');
      }
    }
  } catch (err) {
    console.error('Login error:', err);
    if (loginGeneralError) {
      loginGeneralError.textContent = 'Unable to connect to the server. Please verify your connection.';
      loginGeneralError.classList.remove('hidden');
    }
  } finally {
    btnSubmitLogin.disabled = false;
    if (btnText) btnText.textContent = 'Sign in';
    if (btnArrow) btnArrow.classList.remove('hidden');
    if (btnSpinner) btnSpinner.classList.add('hidden');
  }
}

