function generateUniqueQuoteId() {
  const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const nums = '0123456789';
  let qid = 'QT-2026-';
  for (let i = 0; i < 4; i++) qid += nums.charAt(Math.floor(Math.random() * nums.length));
  qid += letters.charAt(Math.floor(Math.random() * letters.length));
  if (state.drafts && state.drafts.some(d => d.id === qid)) {
    return generateUniqueQuoteId();
  }
  return qid;
}

function saveCurrentAsDraft(customTitle = null, showNotification = true, forceNewId = false) {
  if (!state.quoteId || forceNewId) {
    state.quoteId = generateUniqueQuoteId();
  }
  updateHeaderQuoteBadge();

  const tierObj = pricingConfig.tiers[state.tier] || { name: 'Standard Service Tier', price: 3200 };
  const relObj = pricingConfig.religions[state.religion] || { name: 'Secular Ceremony Rites', price: 500 };
  const tierName = tierObj.name ? tierObj.name.split(' ')[0] : 'Arrangement';
  const relName = relObj.name ? relObj.name.split(' ')[0] : '';
  const title = customTitle || `${tierName} ${relName} Plan`;

  const now = new Date();
  const dateStr = now.toLocaleDateString('en-US', { day: '2-digit', month: 'short', year: 'numeric' });

  const draftData = {
    id: state.quoteId,
    title: title,
    date: dateStr,
    price: state.computedTotal || 4360,
    tier: state.tier,
    religion: state.religion,
    wakeDuration: state.wakeDuration,
    casket: state.casket,
    addons: { ...state.addons },
    signatureDataUrl: state.savedSignatureDataUrl,
    coordination: state.coordination ? { ...state.coordination } : {}
  };

  const existingIndex = state.drafts.findIndex(d => d.id === state.quoteId);
  if (existingIndex >= 0) {
    state.drafts[existingIndex] = draftData;
  } else {
    state.drafts.unshift(draftData);
  }
  persistDrafts();
  // This arrangement is now a proper saved draft, so the loose in-progress copy
  // is no longer needed.
  clearWorkInProgress();

  if (showNotification && simNotification && simNotificationText) {
    const draftSavedTemplates = {
      en: `Draft ${state.quoteId} (${title}) saved to Family Hub!`,
      zh: `草稿 ${state.quoteId}（${title}）已保存至家庭中心！`,
      ms: `Draf ${state.quoteId} (${title}) disimpan ke Hab Keluarga!`,
      ta: `வரைவு ${state.quoteId} (${title}) குடும்ப மையத்தில் சேமிக்கப்பட்டது!`
    };
    const curLang = state.currentLanguage || 'en';
    simNotificationText.textContent = draftSavedTemplates[curLang] || draftSavedTemplates.en;
    simNotification.classList.remove('opacity-0', 'pointer-events-none', '-translate-y-4');
    simNotification.classList.add('opacity-100', 'pointer-events-auto', 'translate-y-0');
    setTimeout(() => {
      simNotification.classList.remove('opacity-100', 'pointer-events-auto', 'translate-y-0');
      simNotification.classList.add('opacity-0', 'pointer-events-none', '-translate-y-4');
    }, 4000);
  }

  renderDashboardSaved();
}

function loadDraft(draft) {
  state.quoteId = draft.id;
  state.tier = draft.tier || 'standard';
  state.religion = draft.religion || 'christian';
  state.wakeDuration = draft.wakeDuration || '3day';
  state.casket = draft.casket || 'standard';
  state.addons = draft.addons ? { ...draft.addons } : {};
  state.savedSignatureDataUrl = draft.signatureDataUrl || null;
  state.hasSignature = !!draft.signatureDataUrl;
  state.timestamp = draft.date || '';

  if (draft.coordination) {
    state.coordination = { ...draft.coordination };
  }

  updateHeaderQuoteBadge();

  renderPlannerSelectors();
  recalculatePlannerPrice();
  if (typeof resizeSignatureCanvas === 'function') {
    resizeSignatureCanvas();
  }
}

// ==========================================
// SESSION & PER-USER STORAGE SCOPING
// ==========================================
const SESSION_TOKEN_KEY = 'solace_session_token';

function getSessionToken() {
  try {
    return sessionStorage.getItem(SESSION_TOKEN_KEY);
  } catch (e) {
    return null;
  }
}

function draftsKey() {
  return `solace_saved_drafts_v1::${(state.user && state.user.id) || 'anon'}`;
}

function wipKey() {
  return `solace_wip_v1::${(state.user && state.user.id) || 'anon'}`;
}

// Migrate unscoped legacy drafts on first user login
function migrateLegacyDrafts(userId) {
  try {
    if (!userId) return;
    const legacyKey = 'solace_saved_drafts_v1';
    const legacyData = localStorage.getItem(legacyKey);
    if (legacyData) {
      const targetKey = `solace_saved_drafts_v1::${userId}`;
      const existing = localStorage.getItem(targetKey);
      if (!existing) {
        localStorage.setItem(targetKey, legacyData);
      }
      localStorage.removeItem(legacyKey);
    }
  } catch (e) {
    console.warn('Draft migration error:', e);
  }
}

let _syncToCloudTimer = null;
function syncToCloud() {
  const token = getSessionToken();
  if (!token || !state.user || !state.user.id || state.user.isGuest) return;

  if (_syncToCloudTimer) clearTimeout(_syncToCloudTimer);
  _syncToCloudTimer = setTimeout(async () => {
    try {
      const wipPayload = {
        tier: state.tier,
        religion: state.religion,
        wakeLocation: state.wakeLocation,
        wakeDuration: state.wakeDuration,
        casket: state.casket,
        ashManagement: state.ashManagement,
        addons: state.addons ? { ...state.addons } : {},
        coordination: state.coordination ? { ...state.coordination } : {},
        quoteId: state.quoteId,
        computedTotal: state.computedTotal
      };
      await fetch(`${API_BASE}/api/user/arrangements`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          wip: wipPayload,
          drafts: state.drafts || []
        })
      });
    } catch (e) {
      console.warn('Could not sync arrangements to cloud:', e);
    }
  }, 400);
}

async function syncFromCloud() {
  const token = getSessionToken();
  if (!token || !state.user || !state.user.id || state.user.isGuest) return;

  try {
    const resp = await fetch(`${API_BASE}/api/user/arrangements`, {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    if (resp.ok) {
      const data = await resp.json();
      if (data && data.success) {
        let hasChanges = false;
        // 1. Restore drafts
        if (Array.isArray(data.drafts) && data.drafts.length > 0) {
          state.drafts = data.drafts;
          try { localStorage.setItem(draftsKey(), JSON.stringify(state.drafts)); } catch (e) {}
          hasChanges = true;
        }
        // 2. Restore WIP
        if (data.wip && typeof data.wip === 'object' && Object.keys(data.wip).length > 0) {
          const w = data.wip;
          if (w.tier) state.tier = w.tier;
          if (w.religion) state.religion = w.religion;
          if (w.wakeLocation) state.wakeLocation = w.wakeLocation;
          if (w.wakeDuration) state.wakeDuration = w.wakeDuration;
          if (w.casket) state.casket = w.casket;
          if (w.ashManagement) state.ashManagement = w.ashManagement;
          if (w.addons) state.addons = { ...state.addons, ...w.addons };
          if (w.coordination) state.coordination = { ...state.coordination, ...w.coordination };
          if (w.quoteId) state.quoteId = w.quoteId;
          try { localStorage.setItem(wipKey(), JSON.stringify(w)); } catch (e) {}
          hasChanges = true;
        }
        if (hasChanges) {
          renderDashboardSaved();
          renderPlannerSelectors();
          recalculatePlannerPrice();
          updateHeaderQuoteBadge();
        }
      }
    }
  } catch (e) {
    console.warn('Could not fetch arrangements from cloud:', e);
  }
}

function persistDrafts() {
  try {
    localStorage.setItem(draftsKey(), JSON.stringify(state.drafts));
  } catch (e) {
    console.warn('Could not save drafts to localStorage:', e);
  }
  syncToCloud();
}

function loadPersistedDrafts() {
  try {
    const raw = localStorage.getItem(draftsKey());
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) state.drafts = parsed;
    } else {
      state.drafts = [];
    }
  } catch (e) {
    console.warn('Could not load drafts from localStorage:', e);
    state.drafts = [];
  }
}

function persistWorkInProgress() {
  try {
    const hasProgress = state.tier || state.religion || state.wakeDuration ||
      state.casket || (state.coordination && Object.keys(state.coordination).length);
    if (!hasProgress) return;
    localStorage.setItem(wipKey(), JSON.stringify({
      tier: state.tier,
      religion: state.religion,
      wakeLocation: state.wakeLocation,
      wakeDuration: state.wakeDuration,
      casket: state.casket,
      ashManagement: state.ashManagement,
      addons: state.addons ? { ...state.addons } : {},
      coordination: state.coordination ? { ...state.coordination } : {},
      quoteId: state.quoteId,
    }));
  } catch (e) {
    console.warn('Could not save work in progress:', e);
  }
  syncToCloud();
}

function loadWorkInProgress() {
  try {
    const raw = localStorage.getItem(wipKey());
    if (!raw) return;
    const wip = JSON.parse(raw);
    if (wip.tier) state.tier = wip.tier;
    if (wip.religion) state.religion = wip.religion;
    if (wip.wakeDuration) state.wakeDuration = wip.wakeDuration;
    if (wip.casket) state.casket = wip.casket;
    if (wip.addons) state.addons = { ...state.addons, ...wip.addons };
    if (wip.coordination) state.coordination = { ...state.coordination, ...wip.coordination };
    if (wip.quoteId) state.quoteId = wip.quoteId;
  } catch (e) {
    console.warn('Could not load work in progress:', e);
  }
}

function clearWorkInProgress() {
  try {
    localStorage.removeItem(wipKey());
  } catch (e) { /* nothing to do */ }
}

function resetArrangementState() {
  state.tier = 'standard';
  state.religion = 'christian';
  state.wakeLocation = 'hdb';
  state.wakeDuration = '3day';
  state.casket = 'standard';
  state.ashManagement = 'cremation';
  state.addons = {
    catering: false,
    actent: false,
    memory: false,
    livestream: false,
    security: false,
    mitsuoka_hearse: false,
    wreaths: false,
    will_planning: false,
    grief_counseling: false
  };
  state.hasSignature = false;
  state.savedSignatureDataUrl = null;
  state.computedSubtotal = 4000;
  state.computedTax = 360;
  state.computedTotal = 4360;
  state.quoteId = null;
  state.timestamp = '';
  state.coordination = {};
  state.drafts = [];
  chatHistory = [];
  if (chatContainer) chatContainer.innerHTML = '';
}

function renderDashboardSaved() {
  if (!dashboardSavedList) return;
  dashboardSavedList.innerHTML = '';
  // Guard against duplicate ids (e.g. older saved data), keeping the first.
  const seenIds = new Set();
  const uniqueDrafts = state.drafts.filter(d => {
    if (seenIds.has(d.id)) return false;
    seenIds.add(d.id);
    return true;
  });
  uniqueDrafts.forEach(draft => {
    const item = document.createElement('div');
    const isCurrent = state.quoteId === draft.id;
    item.className = `p-4 bg-bgPure border ${isCurrent ? 'border-primary ring-1 ring-primary/30' : 'border-highlight hover:border-primary'} rounded-xl cursor-pointer transition-all shadow-2xs hover:shadow-sm space-y-2.5`;

    const hasSig = !!draft.signatureDataUrl;
    const rawTier = pricingConfig.tiers[draft.tier] ? pricingConfig.tiers[draft.tier].name : (draft.tier || 'Standard');
    const rawRel = pricingConfig.religions[draft.religion] ? pricingConfig.religions[draft.religion].name : (draft.religion || 'Secular');
    const rawDur = pricingConfig.durations[draft.wakeDuration] ? pricingConfig.durations[draft.wakeDuration].name : (draft.wakeDuration || '3-Day');
    const rawCasket = pricingConfig.caskets[draft.casket] ? pricingConfig.caskets[draft.casket].name : (draft.casket || 'Standard');

    const tierInfo = locItemName(rawTier);
    const relInfo = locItemName(rawRel);
    const durInfo = locItemName(rawDur);
    const casketInfo = locItemName(rawCasket);

    item.innerHTML = `
      <div class="flex items-start justify-between">
        <div>
          <div class="font-serif font-bold text-[14px] text-textDark flex items-center gap-2">
            <span>${draft.title}</span>
            ${isCurrent ? '<span class="text-[9px] bg-primary text-white font-bold px-2 py-0.5 rounded-full">ACTIVE</span>' : ''}
          </div>
          <div class="text-[11px] text-textMuted mt-0.5">ID: ${draft.id} &bull; Saved ${draft.date}</div>
        </div>
        <div class="text-right flex flex-col items-end gap-1">
          <div class="font-serif font-bold text-sm text-primary">$${(draft.price || 0).toLocaleString()}</div>
          ${hasSig ? '' : `<button type="button" class="draft-delete-btn text-textMuted/50 hover:text-ember transition-colors p-1 -mr-1 rounded" aria-label="Delete this saved arrangement" title="Delete"><svg class="w-3.5 h-3.5 fill-current" viewBox="0 0 24 24"><path d="M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z"/></svg></button>`}
        </div>
      </div>

      <div class="flex flex-wrap items-center gap-1.5 text-[10px]">
        <span class="bg-fillColor text-textDark font-medium px-2 py-0.5 rounded border border-highlight/50">${tierInfo}</span>
        <span class="bg-fillColor text-textDark font-medium px-2 py-0.5 rounded border border-highlight/50">${relInfo}</span>
        <span class="bg-fillColor text-textDark font-medium px-2 py-0.5 rounded border border-highlight/50">${durInfo}</span>
        <span class="bg-fillColor text-textDark font-medium px-2 py-0.5 rounded border border-highlight/50">${casketInfo}</span>
      </div>

      <div class="pt-2 border-t border-borderLight/60 flex items-center justify-between text-[10px]">
        <div class="flex items-center gap-1.5">
          <span class="text-textMuted font-semibold">Signature:</span>
          ${hasSig ? `<div class="flex items-center gap-1.5 bg-primary/10 text-primary border border-primary/30 px-2 py-0.5 rounded font-bold"><img src="${draft.signatureDataUrl}" class="h-3.5 max-w-[60px] object-contain" /><span>✓ Signed</span></div>` : '<span class="text-textMuted italic bg-fillColor px-2 py-0.5 rounded border border-borderLight">Pending Signature</span>'}
        </div>
        <span class="text-secondary font-bold hover:underline">Load Setup &rarr;</span>
      </div>
    `;

    item.addEventListener('click', () => {
      loadDraft(draft);
      navigateTo('4');
    });

    // Delete. stopPropagation so tapping the bin does not also fire the card's
    // load handler. A confirm() guards against an accidental tap wiping an
    // arrangement the family spent time on.
    const delBtn = item.querySelector('.draft-delete-btn');
    if (delBtn) {
      delBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        // Locked (signed) arrangements are final and cannot be deleted. The
        // button is not even rendered for them, but guard here too.
        if (draft.signatureDataUrl) return;
        const ok = window.confirm(`Delete "${draft.title}"? This cannot be undone.`);
        if (!ok) return;
        state.drafts = state.drafts.filter(d => d.id !== draft.id);
        persistDrafts();
        renderDashboardSaved();
      });
    }

    dashboardSavedList.appendChild(item);
  });
}

