// ==========================================
// AI MODE INDICATOR (header badge + status dot)
// ==========================================
async function refreshAiModeIndicator() {
  const badge = document.getElementById('ai-mode-badge');
  const dot = document.getElementById('header-status-dot');
  if (!badge) return;

  const setBadge = (label, title, badgeClasses, dotClasses) => {
    badge.textContent = label;
    badge.title = title;
    // header-eyebrow keeps the badge in the same letterspaced small-caps voice
    // as the rest of the header; the state colour is the only thing that
    // varies, so an offline model is noticeable without being alarming.
    badge.className = 'header-eyebrow cursor-default select-none ' + badgeClasses;
    if (dot) {
      dot.className =
        'absolute bottom-0 right-0 w-2.5 h-2.5 border-2 border-bgPure rounded-full ' + dotClasses;
    }
  };

  try {
    const res = await fetch(STATUS_URL);
    if (!res.ok) throw new Error('status endpoint returned ' + res.status);
    const data = await res.json();

    if (data.online) {
      setBadge(
        'AI ONLINE',
        `Full AI understanding — ${data.detail}`,
        'text-successColor',
        'bg-successColor status-dot-active'
      );
    } else {
      setBadge(
        'OFFLINE MODE',
        `Limited rule-based replies — ${data.detail}`,
        'text-primary',
        'bg-highlight'
      );
    }
  } catch (err) {
    // Backend itself unreachable (uvicorn not running / wrong port)
    setBadge(
      'NO BACKEND',
      'Cannot reach the backend server on port 8000. Is uvicorn running?',
      'text-red-600',
      'bg-red-500'
    );
  }
}

// Check and restore active user session, or load anon-scoped data
checkAndRestoreSession();

// Check on load, then every 15s so it updates if Ollama is started mid-session
refreshAiModeIndicator();
setInterval(refreshAiModeIndicator, 15000);
let chatHistory = [];

function formatChatMarkdown(text) {
  if (!text) return '';

  // Escape HTML tags to prevent XSS
  let html = text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  // Format bold text **bold** -> <strong>bold</strong>
  html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

  // Convert inline asterisk list items like " **Tier 1** * Item 1 * Item 2" to newlines
  html = html.replace(/([^\n])\s*\*\s+/g, '$1\n- ');

  const lines = html.split('\n');
  let result = '';
  let inList = false;

  lines.forEach(line => {
    const trimmed = line.trim();
    const bulletMatch = trimmed.match(/^[-*•]\s+(.*)$/);
    const numberMatch = trimmed.match(/^(\d+)\.\s+(.*)$/);

    if (bulletMatch) {
      if (!inList) {
        result += '<ul class="my-2 space-y-1 list-disc list-inside text-textDark">';
        inList = 'ul';
      }
      result += `<li class="ml-1">${bulletMatch[1]}</li>`;
    } else if (numberMatch) {
      if (!inList) {
        result += '<ol class="my-2 space-y-1 list-decimal list-inside text-textDark">';
        inList = 'ol';
      }
      result += `<li class="ml-1">${numberMatch[2]}</li>`;
    } else {
      if (inList) {
        result += inList === 'ol' ? '</ol>' : '</ul>';
        inList = false;
      }
      if (trimmed.length > 0) {
        if (result.length > 0 && !result.endsWith('>')) {
          result += '<br>';
        }
        result += trimmed;
      }
    }
  });

  if (inList) {
    result += inList === 'ol' ? '</ol>' : '</ul>';
  }

  return result;
}

// Tracks who spoke last, so a run of messages from the same person only
// carries one name label instead of repeating it on every bubble.
let lastBubbleSpeaker = null;

function resetBubbleGrouping() {
  lastBubbleSpeaker = null;
}

// ---------------------------------------------------------------------------
// Scroll behaviour
//
// Forcing the feed to the bottom on every arriving message pulls the reader
// away from whatever they were part-way through. Only follow if they were
// already at the bottom; otherwise leave them alone and offer a pill.
// ---------------------------------------------------------------------------
const SCROLL_STICK_PX = 80;

function isNearBottom(el) {
  if (!el) return true;
  return el.scrollHeight - el.scrollTop - el.clientHeight < SCROLL_STICK_PX;
}

function scrollChatToBottom(smooth = true) {
  if (!chatContainer) return;
  if (smooth && typeof chatContainer.scrollTo === 'function') {
    chatContainer.scrollTo({
      top: chatContainer.scrollHeight,
      behavior: 'smooth'
    });
  } else {
    chatContainer.scrollTop = chatContainer.scrollHeight;
  }
}

function maybeScrollChat(wasAtBottom) {
  if (wasAtBottom) {
    requestAnimationFrame(() => {
      scrollChatToBottom(true);
    });
    setTimeout(() => {
      scrollChatToBottom(true);
    }, 60);
    hideNewMessagePill();
  } else {
    showNewMessagePill();
  }
}

let newMessagePill = null;

function showNewMessagePill() {
  if (!chatContainer || !chatContainer.parentElement) return;
  if (newMessagePill) return;

  // Sticky INSIDE the scrolling feed, not absolute against the panel. Anchoring
  // it to the panel put it on top of the message input, where it covered the
  // thing the family was about to type into.
  const row = document.createElement('div');
  row.className = 'sticky bottom-2 z-20 w-full flex justify-center pointer-events-none';

  newMessagePill = document.createElement('button');
  newMessagePill.type = 'button';
  newMessagePill.setAttribute('aria-label', 'Scroll to newest message');
  newMessagePill.className = 'pointer-events-auto px-3 py-1.5 rounded-full bg-primary text-white text-[11px] font-semibold shadow-md hover:bg-primaryHover transition-all cursor-pointer';
  newMessagePill.innerText = 'New message \u2193';
  newMessagePill.addEventListener('click', () => {
    scrollChatToBottom();
    hideNewMessagePill();
  });

  row.appendChild(newMessagePill);
  newMessagePill._row = row;
  chatContainer.appendChild(row);
}

function hideNewMessagePill() {
  if (newMessagePill) {
    if (newMessagePill._row) newMessagePill._row.remove();
    else newMessagePill.remove();
    newMessagePill = null;
  }
}

if (chatContainer) {
  chatContainer.addEventListener('scroll', () => {
    if (isNearBottom(chatContainer)) hideNewMessagePill();
  });
}

// ---------------------------------------------------------------------------
// A one-time reassurance under the greeting rather than a permanent line under
// the input. Something the family reads once, so it scrolls away with the rest
// of the conversation instead of taking chat space forever.
function appendFirstLoadNote() {
  const row = document.createElement('div');
  row.className = 'w-full flex justify-center pt-1 pb-1';
  row.innerHTML = '<span class="text-[9.5px] text-textMuted/70 text-center leading-snug max-w-[16rem] px-3 py-1.5 rounded-lg bg-fillColor/60">' +
    escapeHtml(tr('chat_price_disclaimer', 'Prices are exact and come from our catalogue. Legal and CPF questions are passed to a consultant.')) + '</span>';
  if (typingIndicator) {
    chatContainer.insertBefore(row, typingIndicator);
  } else {
    chatContainer.appendChild(row);
  }
}

// Handoff rule
// ---------------------------------------------------------------------------
let handoffRuleShown = { joined: false, ended: false };

function appendHandoffRule(staffName, kind) {
  if (handoffRuleShown[kind]) return;
  handoffRuleShown[kind] = true;

  const label = kind === 'joined'
    ? `${(staffName || '').replace(/\s*\(.*?\)\s*/g, '')} joined \u00b7 ${formatMessageTime(new Date())}`
    : `Consultation ended \u00b7 ${formatMessageTime(new Date())}`;

  const row = document.createElement('div');
  row.className = 'handoff-rule w-full flex items-center gap-3 py-3';
  row.innerHTML = `
    <span class="handoff-rule-line"></span>
    <span class="handoff-rule-label">${escapeHtml(label)}</span>
    <span class="handoff-rule-line"></span>
  `;

  if (typingIndicator) {
    chatContainer.insertBefore(row, typingIndicator);
  } else {
    chatContainer.appendChild(row);
  }
  scrollChatToBottom(true);
}

// Date separators
// ---------------------------------------------------------------------------
let lastMessageDateKey = null;

function dateKey(d) {
  return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
}

// Single lookup for dictionary strings used by JS renderers. Falls back to
// English, then to the supplied default, so a key missing from one language
// never surfaces as a raw key name on screen.
function tr(key, fallback) {
  const all = (typeof I18N_TRANSLATIONS !== 'undefined') ? I18N_TRANSLATIONS : {};
  const lang = (state && state.currentLanguage) || 'en';
  const d = all[lang] || all.en || {};
  return d[key] || (all.en && all.en[key]) || fallback || key;
}

function friendlyDateLabel(d) {
  const today = new Date();
  const yesterday = new Date();
  yesterday.setDate(today.getDate() - 1);
  if (dateKey(d) === dateKey(today)) return tr('chat_date_today', 'Today');
  if (dateKey(d) === dateKey(yesterday)) return tr('chat_date_yesterday', 'Yesterday');
  // Pass the active language so month names localise too, not just the label.
  const dtLocale = { en: 'en-SG', zh: 'zh-SG', ms: 'ms-SG', ta: 'ta-SG' }[(state && state.currentLanguage) || 'en'] || 'en-SG';
  return d.toLocaleDateString(dtLocale, { day: 'numeric', month: 'short', year: 'numeric' });
}

function maybeAppendDateSeparator() {
  const now = new Date();
  const key = dateKey(now);
  if (lastMessageDateKey === key) return;
  lastMessageDateKey = key;

  const row = document.createElement('div');
  row.className = 'w-full flex justify-center py-2';
  row.innerHTML = `<span class="text-[10px] font-semibold uppercase tracking-wider text-textMuted/70 bg-fillColor px-3 py-1 rounded-full">${escapeHtml(friendlyDateLabel(now))}</span>`;
  if (typingIndicator) {
    chatContainer.insertBefore(row, typingIndicator);
  } else {
    chatContainer.appendChild(row);
  }
}

// Centred announcement line — not someone speaking, so it gets no bubble.
function appendSystemLine(text) {
  const row = document.createElement('div');
  row.className = 'w-full py-2 flex justify-center';
  row.innerHTML = `<span class="text-[11px] text-textMuted/80 text-center max-w-[80%] leading-relaxed">${escapeHtml(text)}</span>`;

  if (typingIndicator) {
    chatContainer.insertBefore(row, typingIndicator);
  } else {
    chatContainer.appendChild(row);
  }
  scrollChatToBottom(true);
  lastBubbleSpeaker = null;
  return row;
}

// 12-hour timestamp, e.g. "10:24 am". Lowercase am/pm to match the design.
function formatMessageTime(date) {
  const d = date instanceof Date ? date : new Date();
  let hours = d.getHours();
  const minutes = String(d.getMinutes()).padStart(2, '0');
  const suffix = hours >= 12 ? 'pm' : 'am';
  hours = hours % 12;
  if (hours === 0) hours = 12;
  return `${hours}:${minutes} ${suffix}`;
}

const CLAMP_STEP_LINES = 5;

// Clamping is measured in lines, not characters, because a bubble's height is
// what actually matters to the reader. Each "Show more" reveals another five
// lines rather than the whole message, so a long paste expands gradually
// instead of pushing everything else off screen in one jump.
function applyProgressiveClamp(textEl, bubbleEl) {
  const lineHeight = parseFloat(getComputedStyle(textEl).lineHeight) || 20;
  const totalLines = Math.round(textEl.scrollHeight / lineHeight);
  if (totalLines <= CLAMP_STEP_LINES) return;

  let shownLines = CLAMP_STEP_LINES;

  const controls = document.createElement('div');
  controls.className = 'mt-1.5 flex gap-3';

  const moreBtn = document.createElement('button');
  moreBtn.type = 'button';
  moreBtn.className = 'text-[11px] font-semibold underline underline-offset-2 opacity-80 hover:opacity-100 cursor-pointer';

  const lessBtn = document.createElement('button');
  lessBtn.type = 'button';
  lessBtn.className = 'text-[11px] font-semibold underline underline-offset-2 opacity-80 hover:opacity-100 cursor-pointer';
  lessBtn.innerText = 'Show less \u25b4';
  lessBtn.style.display = 'none';

  function render() {
    if (shownLines >= totalLines) {
      // Setting the line count inline is unreliable across browsers because
      // -webkit-line-clamp needs display and box-orient set together. A class
      // plus a custom property keeps all three in the stylesheet.
      textEl.classList.remove('chat-clamp');
      moreBtn.style.display = 'none';
    } else {
      textEl.classList.add('chat-clamp');
      textEl.style.setProperty('--clamp-lines', String(shownLines));
      moreBtn.style.display = '';
      moreBtn.innerText = 'Show more \u25be';
    }
    lessBtn.style.display = shownLines > CLAMP_STEP_LINES ? '' : 'none';
  }

  // No scrollTop assignment in either handler. Forcing the feed to the bottom
  // on expand threw the reader out of the message they were part-way through
  // reading; leaving scroll alone keeps the bubble and everything above it
  // exactly where they were.
  moreBtn.addEventListener('click', () => {
    shownLines += CLAMP_STEP_LINES;
    render();
  });

  lessBtn.addEventListener('click', () => {
    shownLines = CLAMP_STEP_LINES;
    render();
  });

  textEl.classList.add('chat-clamp');

  controls.appendChild(moreBtn);
  controls.appendChild(lessBtn);
  bubbleEl.appendChild(controls);
  render();
}

function appendBubble(text, sender, speakerName) {
  // A human consultant's messages are tinted and labelled differently from
  // the assistant's, so the handoff is visible at a glance.
  const isStaff = sender === 'staff';
  const isUser = sender === 'user';
  const speakerKey = isStaff ? `staff:${speakerName || ''}` : sender;

  if (isStaff && speakerName && lastBubbleSpeaker !== speakerKey) {
    const label = document.createElement('div');
    label.className = 'flex justify-start w-full';
    label.innerHTML = `<span class="text-[10px] font-semibold text-primary tracking-wide pl-1">${escapeHtml(speakerName)}</span>`;
    if (typingIndicator) {
      chatContainer.insertBefore(label, typingIndicator);
    } else {
      chatContainer.appendChild(label);
    }
  }
  lastBubbleSpeaker = speakerKey;

  maybeAppendDateSeparator();
  const wasAtBottom = isNearBottom(chatContainer);

  const bubble = document.createElement('div');
  bubble.className = `flex ${isUser ? 'justify-end' : 'justify-start'} w-full`;


  let bubbleStyle, tailClass;
  if (isUser) {
    bubbleStyle = 'bg-primary text-white rounded-2xl rounded-tr-none shadow-sm';
    tailClass = 'chat-bubble-user';
  } else if (isStaff) {
    bubbleStyle = 'bg-fillColor border border-highlight border-l-[3px] border-l-primary text-textDark rounded-2xl rounded-tl-none shadow-sm';
    tailClass = 'chat-bubble-staff';
  } else {
    bubbleStyle = 'bg-bgPure border border-borderLight text-textDark rounded-2xl rounded-tl-none shadow-sm';
    tailClass = 'chat-bubble-ai';
  }

  const innerBubble = document.createElement('div');
  // break-words handles normal long text; overflow-wrap:anywhere and
  // word-break:break-word are what stop an unbroken string — a pasted URL, or
  // 300 characters with no spaces — from pushing the bubble past the screen.
  innerBubble.className = `relative max-w-[85%] p-4 text-sm leading-relaxed break-words [overflow-wrap:anywhere] [word-break:break-word] ${bubbleStyle} ${tailClass}`;

  const textEl = document.createElement('div');
  if (isUser) {
    textEl.innerText = text;
  } else {
    textEl.innerHTML = formatChatMarkdown(text);
  }
  innerBubble.appendChild(textEl);

  const stamp = document.createElement('div');
  stamp.className = `text-[10px] mt-1 text-right ${isUser ? 'text-white/70' : 'text-textMuted/70'}`;
  stamp.innerText = formatMessageTime(new Date());
  innerBubble.appendChild(stamp);

  bubble.appendChild(innerBubble);

  if (typingIndicator) {
    chatContainer.insertBefore(bubble, typingIndicator);
  } else {
    chatContainer.appendChild(bubble);
  }

  // Clamp only the family's own messages. An assistant reply is the thing the
  // family is waiting to read, so hiding four fifths of it behind a button
  // would be the wrong trade.
  if (isUser) {
    applyProgressiveClamp(textEl, innerBubble);
  } else {
    attachCopyButton(innerBubble, text);
    // Only attach voice TTS guidance for AI assistant messages; omit for human funeral consultant messages
    if (!isStaff) {
      attachTTSButton(innerBubble, text);
    }
  }

  maybeScrollChat(wasAtBottom);
  return innerBubble;
}

// Clean markdown text for gentle speech synthesis
function cleanTextForSpeech(text) {
  return text
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/\*(.*?)\*/g, '$1')
    .replace(/\[(.*?)\]\(.*?\)/g, '$1')
    .replace(/#{1,6}\s+/g, '')
    .replace(/`{1,3}.*?`{1,3}/g, '')
    .replace(/[-*•]\s+/g, '')
    .replace(/\n+/g, ' ')
    .trim();
}

let currentPlayingBtn = null;
let currentKokoroAudio = null;

function stopCurrentSpeech() {
  if (currentKokoroAudio) {
    try {
      currentKokoroAudio.pause();
      currentKokoroAudio.currentTime = 0;
    } catch (e) {}
    currentKokoroAudio = null;
  }
  if ('speechSynthesis' in window) {
    try { window.speechSynthesis.cancel(); } catch (e) {}
  }
  if (currentPlayingBtn) {
    currentPlayingBtn.classList.remove('speaking');
    currentPlayingBtn.innerHTML = `
      <svg class="w-3.5 h-3.5 fill-current" viewBox="0 0 24 24">
        <path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z"/>
      </svg>
    `;
    currentPlayingBtn = null;
  }
}

// Preload and lock soothing female voice on load
let cachedFemaleVoice = null;

function loadAndCacheFemaleVoice() {
  if (!('speechSynthesis' in window)) return;
  const voices = window.speechSynthesis.getVoices();
  if (!voices || voices.length === 0) return;

  const femaleVoiceNames = [
    'Samantha', 'Karen', 'Serena', 'Moira', 'Tessa', 'Victoria', 'Fiona',
    'Google UK English Female', 'Google US English Female', 'Google US English',
    'Microsoft Jenny Online', 'Microsoft Aria Online',
    'Microsoft Sonia Online', 'Microsoft Zira', 'Microsoft Jenny',
    'Microsoft Aria'
  ];

  for (const name of femaleVoiceNames) {
    const found = voices.find(v => v.name.toLowerCase().includes(name.toLowerCase()));
    if (found) {
      cachedFemaleVoice = found;
      return;
    }
  }

  cachedFemaleVoice = voices.find(v => 
    (v.lang.includes('SG') || v.lang.includes('GB') || v.lang.includes('en')) &&
    (v.name.toLowerCase().includes('female') || !(/male|david|mark|george|daniel|guy|richard|stefan/i.test(v.name)))
  ) || voices[0];
}

if ('speechSynthesis' in window) {
  loadAndCacheFemaleVoice();
  window.speechSynthesis.onvoiceschanged = loadAndCacheFemaleVoice;
}

function attachTTSButton(bubbleEl, rawText) {
  const clean = cleanTextForSpeech(rawText);
  if (!clean || clean.length < 4) return;

  const currentLang = state.currentLanguage || 'en';
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'tts-play-btn';
  btn.setAttribute('aria-label', 'Play audio guidance');
  btn.title = 'Listen to voice guidance';
  btn.innerHTML = `
    <svg class="w-3.5 h-3.5 fill-current" viewBox="0 0 24 24">
      <path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z"/>
    </svg>
  `;

  // Pre-generate audio in background for English with Kokoro
  let preloadedAudioUrl = null;
  if (currentLang === 'en') {
    fetch(`${API_BASE}/api/speak`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text: clean, voice: 'af_heart', speed: 0.92 })
    }).then(async (resp) => {
      if (resp.ok) {
        const blob = await resp.blob();
        preloadedAudioUrl = URL.createObjectURL(blob);
      }
    }).catch(() => {});
  }

  btn.addEventListener('click', async (e) => {
    e.stopPropagation();
    if (btn === currentPlayingBtn) {
      stopCurrentSpeech();
      return;
    }

    stopCurrentSpeech();

    // Multilingual Voice Handling for Chinese, Malay, Tamil
    if (currentLang !== 'en') {
      if (!('speechSynthesis' in window)) return;
      btn.classList.add('speaking');
      btn.innerHTML = `
        <svg class="w-3.5 h-3.5 fill-current animate-pulse" viewBox="0 0 24 24">
          <path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/>
        </svg>
      `;
      currentPlayingBtn = btn;

      const utterance = new SpeechSynthesisUtterance(clean);
      const voices = window.speechSynthesis.getVoices() || [];

      if (currentLang === 'zh') {
        utterance.lang = 'zh-SG';
        utterance.rate = 0.90;
        const zhVoice = voices.find(v => v.lang.includes('zh') || v.lang.includes('cmn'));
        if (zhVoice) utterance.voice = zhVoice;
      } else if (currentLang === 'ms') {
        utterance.lang = 'ms-MY';
        utterance.rate = 0.88;
        const msVoice = voices.find(v => v.lang.includes('ms') || v.lang.includes('id') || v.lang.includes('Malay'));
        if (msVoice) utterance.voice = msVoice;
      } else if (currentLang === 'ta') {
        utterance.lang = 'ta-SG';
        utterance.rate = 0.85;
        const taVoice = voices.find(v => v.lang.includes('ta') || v.lang.includes('Tamil'));
        if (taVoice) utterance.voice = taVoice;
      }

      utterance.onend = () => stopCurrentSpeech();
      utterance.onerror = () => stopCurrentSpeech();
      window.speechSynthesis.speak(utterance);
      return;
    }

    // Instant playback if preloaded in background (English Kokoro)
    if (preloadedAudioUrl) {
      const audio = new Audio(preloadedAudioUrl);
      currentKokoroAudio = audio;
      currentPlayingBtn = btn;

      btn.classList.add('speaking');
      btn.innerHTML = `
        <svg class="w-3.5 h-3.5 fill-current animate-pulse" viewBox="0 0 24 24">
          <path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/>
        </svg>
      `;

      audio.onended = () => stopCurrentSpeech();
      audio.onerror = () => stopCurrentSpeech();

      try {
        await audio.play();
        return;
      } catch (err) {
        console.warn('Audio playback error:', err);
      }
    }

    btn.classList.add('loading');
    currentPlayingBtn = btn;

    // Fetch Kokoro if not yet preloaded
    try {
      const resp = await fetch(`${API_BASE}/api/speak`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: clean, voice: 'af_heart', speed: 0.92 })
      });

      if (resp.ok) {
        const blob = await resp.blob();
        preloadedAudioUrl = URL.createObjectURL(blob);
        const audio = new Audio(preloadedAudioUrl);
        currentKokoroAudio = audio;

        btn.classList.remove('loading');
        btn.classList.add('speaking');
        btn.innerHTML = `
          <svg class="w-3.5 h-3.5 fill-current animate-pulse" viewBox="0 0 24 24">
            <path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/>
          </svg>
        `;

        audio.onended = () => stopCurrentSpeech();
        audio.onerror = () => stopCurrentSpeech();

        await audio.play();
        return;
      }
    } catch (err) {
      console.warn('[Kokoro TTS] Fallback to WebSpeech:', err);
    }

    btn.classList.remove('loading');
    btn.classList.add('speaking');
    btn.innerHTML = `
      <svg class="w-3.5 h-3.5 fill-current animate-pulse" viewBox="0 0 24 24">
        <path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/>
      </svg>
    `;

    // WebSpeech Fallback for English
    if ('speechSynthesis' in window) {
      if (!cachedFemaleVoice) loadAndCacheFemaleVoice();
      const utterance = new SpeechSynthesisUtterance(clean);
      utterance.lang = 'en-SG';
      utterance.rate = 0.88;
      utterance.pitch = 0.95;
      if (cachedFemaleVoice) utterance.voice = cachedFemaleVoice;

      utterance.onend = () => stopCurrentSpeech();
      utterance.onerror = () => stopCurrentSpeech();

      window.speechSynthesis.speak(utterance);
    } else {
      stopCurrentSpeech();
    }
  });

  bubbleEl.appendChild(btn);
}


// Families want to keep the price breakdown or the emergency steps. One click
// beats selecting text on a phone.
function attachCopyButton(bubbleEl, rawText) {
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.setAttribute('aria-label', 'Copy this message');
  btn.title = 'Copy';
  btn.className = 'absolute top-1.5 right-1.5 w-6 h-6 rounded-md text-textMuted/60 hover:text-primary hover:bg-fillColor opacity-0 group-hover:opacity-100 focus-visible:opacity-100 transition-opacity flex items-center justify-center cursor-pointer';
  btn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>';

  btn.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(rawText);
    } catch (err) {
      // Clipboard API needs a secure context. Over plain http on a phone it
      // throws, so fall back to a hidden textarea rather than failing silently.
      const ta = document.createElement('textarea');
      ta.value = rawText;
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand('copy'); } catch (e) { /* nothing more to try */ }
      ta.remove();
    }
    const original = btn.innerHTML;
    btn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 6 9 17l-5-5"/></svg>';
    setTimeout(() => { btn.innerHTML = original; }, 1400);
  });

  bubbleEl.classList.add('group');
  bubbleEl.appendChild(btn);
}

// Detects the AI's "intake complete" message so we can surface a direct-navigation button
function isIntakeCompleteMessage(text) {
  if (!text) return false;
  const lower = text.toLowerCase();
  return lower.includes('proceed to the planner') || lower.includes('we have everything we need') || lower.includes('arrangement finalized') || lower.includes('quote complete');
}

function getStepOptionsForMessage(text) {
  if (!text) return null;
  const lower = text.toLowerCase();

  // Once at intake completion, omit step options buttons so human/AI conversation proceeds naturally
  if (lower.includes('proceed to the planner') || lower.includes('we have everything we need')) {
    return null;
  }

  // Final Confirmation Summary
  if (lower.includes('before we finalise') || lower.includes('is everything correct') || lower.includes('would you like to change anything')) {
    return [
      { label: 'Yes, Everything is Correct (Lock in Quote)', text: 'Yes, everything is correct' },
      { label: 'I want to change something', text: 'I would like to change some details' },
      { label: 'Speak to a Consultant', action: openConsultantModal, accent: true }
    ];
  }

  // Deceased Name / Date of Birth / Date of Passing (Open text input, no quick chips needed)
  if (lower.includes('name of your departed loved one') || lower.includes('date of birth') || lower.includes('when did your loved one pass')) {
    return null;
  }

  // Location of Deceased
  if (lower.includes('where is your loved one resting') || lower.includes('resting at the moment') || lower.includes('hospital, hospice, or at home')) {
    return [
      { label: 'Hospital', text: 'Hospital' },
      { label: 'Home', text: 'Home' },
      { label: 'Hospice', text: 'Hospice' },
      { label: 'Unsure for now', text: 'Unsure for now' }
    ];
  }

  // Next of Kin
  if (lower.includes('are you the next of kin') || lower.includes('authorised by the family')) {
    return [
      { label: 'Yes, Next of Kin', text: 'Yes, I am the next of kin' },
      { label: 'Authorised Family Member', text: 'I am an authorised family representative' }
    ];
  }

  // Religion / Rites
  if ((lower.includes('prefer a christian') || lower.includes('which religion') || lower.includes('religious rites') || lower.includes('christian, buddhist, taoist') || lower.includes('service rites')) && !lower.includes('before we finalise')) {
    return [
      { label: 'Christian', text: 'Christian' },
      { label: 'Buddhist', text: 'Buddhist' },
      { label: 'Taoist', text: 'Taoist' },
      { label: 'Soka Gakkai', text: 'Soka Gakkai' },
      { label: 'Catholic', text: 'Catholic' },
      { label: 'Free Thinker', text: 'Free Thinker' },
      { label: 'Hindu', text: 'Hindu' },
      { label: 'Secular', text: 'Secular' }
    ];
  }

  // Service Package Tier
  if (lower.includes('which service tier fits your family best') || lower.includes('standard, deluxe, or premium')) {
    return [
      { label: 'Direct Cremation ($1,500)', text: 'Direct Cremation package' },
      { label: 'Standard ($3,200)', text: 'Standard tier' },
      { label: 'Deluxe ($4,500)', text: 'Deluxe tier' },
      { label: 'Premium ($6,800)', text: 'Premium tier' }
    ];
  }

  // Casket
  if (lower.includes('eco-wood, oak, or teak casket') || lower.includes('prefer the eco-wood')) {
    return [
      { label: 'Eco-Wood (Included)', text: 'Eco-Wood casket' },
      { label: 'Oak (+$1,200)', text: 'Oak casket' },
      { label: 'Teak (+$2,800)', text: 'Teak casket' }
    ];
  }

  // Final Disposition
  if (lower.includes('cremation at mandai crematorium or burial') || lower.includes('final disposition')) {
    return [
      { label: 'Cremation (Mandai)', text: 'Cremation at Mandai' },
      { label: 'Burial (Choa Chu Kang)', text: 'Burial at Choa Chu Kang' }
    ];
  }

  // Ash Management
  if (lower.includes('ash management') || lower.includes('inland ash scattering') || lower.includes('columbarium') || lower.includes('sea scattering') || lower.includes('keepsake jewellery')) {
    return [
      { label: 'Mandai Placement', text: 'Mandai Crematorium Placement' },
      { label: 'Inland Scattering ($350)', text: 'Inland Ash Scattering at Garden of Peace' },
      { label: 'Sea Scattering ($380)', text: 'Sea Scattering Ceremony' },
      { label: 'Columbarium Niche ($1,200)', text: 'Columbarium Niche Placement' },
      { label: 'Keepsake Jewellery ($250)', text: 'Memorial Keepsake Urn Jewellery' }
    ];
  }

  // Wake Duration
  if (lower.includes('wake coordination suit') || lower.includes('3-day') || lower.includes('5-day') || lower.includes('7-day')) {
    return [
      { label: '3-Day Wake (Included)', text: '3-Day wake' },
      { label: '5-Day Wake (+$800)', text: '5-Day wake' },
      { label: '7-Day Wake (+$1,500)', text: '7-Day wake' }
    ];
  }

  // Wake Location
  if (lower.includes('hdb void deck') || lower.includes('parlour') || lower.includes('where would you prefer to hold the wake') || lower.includes('wake location') || lower.includes('main office in woodlands')) {
    return [
      { label: 'HDB Void Deck (Included)', text: 'HDB Void Deck Setup' },
      { label: 'Direct Memorial Hall (+$1,200/day)', text: 'Direct Memorial Hall Air-Con Parlour' },
      { label: 'Private Residence', text: 'Private Residence' }
    ];
  }

  // Expected Guests
  if (lower.includes('how many guests') || lower.includes('guest count') || lower.includes('expecting guests') || lower.includes('catering portions') || lower.includes('seating and catering')) {
    return [
      { label: 'Under 30 Guests', text: 'Around 20-30 guests' },
      { label: '30 - 50 Guests', text: 'Around 50 guests' },
      { label: '50 - 100 Guests', text: 'Around 80-100 guests' },
      { label: '100+ Guests', text: 'More than 100 guests' }
    ];
  }

  // Add-ons
  if (!lower.includes('how many guests') && !lower.includes('catering portions') && (lower.includes('additions like') || lower.includes('optional add-on') || lower.includes('add-ons') || lower.includes('memory video') || lower.includes('mitsuoka hearse') || lower.includes('floral wreath') || lower.includes('will planning') || lower.includes('no add-ons needed') || lower.includes('additional services') || lower.includes('catering ($450/day)'))) {
    return [
      { label: 'Add Catering ($450/day)', text: 'Add Catering' },
      { label: 'Air-Con Tentage ($900)', text: 'Add Tentage' },
      { label: 'Memory Video ($350)', text: 'Add Memory Video' },
      { label: 'Mitsuoka Hearse ($600)', text: 'Add Mitsuoka Hearse' },
      { label: 'Floral Wreaths ($250)', text: 'Add Floral Wreath Set' },
      { label: 'Will Planning ($350)', text: 'Add Will Writing' },
      { label: 'No add-ons needed', text: 'No add-ons needed' }
    ];
  }

  // Documentation status
  if (lower.includes('death certificate or certificate of cause of death') || lower.includes('have the death certificate')) {
    return [
      { label: 'Yes, Certificate Ready', text: 'Yes, we have the death certificate ready' },
      { label: 'No, Need Guidance', text: 'Not yet, please guide us' }
    ];
  }

  // Payment Preference
  if (lower.includes('pay in full, or set up') || lower.includes('interest-free installment plans') || lower.includes('installment plan') || lower.includes('lump sum on completion, or interest-free 12-month') || lower.includes('flexible options: lump sum') || lower.includes('payment preference')) {
    return [
      { label: 'Pay in Full (Lump Sum)', text: 'Pay in full' },
      { label: 'Interest-Free Installments', text: 'Set up an interest-free installment plan' }
    ];
  }

  return null;
}

function getInitialDefaultOptions() {
  const lang = state.currentLanguage || 'en';
  const getPreset = (key) => (LOCALIZED_PRESETS[key] && LOCALIZED_PRESETS[key][lang]) || (LOCALIZED_PRESETS[key] && LOCALIZED_PRESETS[key]['en']) || '';

  return [
    { label: tr('chip_speak_consultant'), action: openConsultantModal, accent: true, hideInHumanMode: true },
    { label: tr('chip_step_by_step'), text: getPreset('step_by_step') },
    { label: tr('chip_packages_pricing'), text: getPreset('packages_pricing') },
    { label: tr('chip_planning_stages'), text: getPreset('planning_stages') },
    { label: tr('chip_go_planner'), action: () => navigateTo('4') }
  ];
}

const CHIP_BASE_CLASS = 'quick-chip whitespace-nowrap px-3 py-1.5 rounded-xl font-semibold transition-all shadow-2xs cursor-pointer shrink-0';
const CHIP_DEFAULT_CLASS = `${CHIP_BASE_CLASS} bg-fillColor hover:bg-highlight/40 text-textDark border border-highlight/60`;
const CHIP_ACCENT_CLASS = `${CHIP_BASE_CLASS} bg-bgPure hover:bg-fillColor text-primary border border-primary/70`;

// How long a family has been waiting, phrased the way a director would
// say it out loud rather than as a raw timestamp.
function formatWaitingFor(isoString) {
  const started = new Date(isoString).getTime();
  if (!isoString || isNaN(started)) return '';

  const seconds = Math.max(0, Math.floor((Date.now() - started) / 1000));
  if (seconds < 60) return 'just now';

  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes} min`;

  const hours = Math.floor(minutes / 60);
  const remainder = minutes % 60;
  if (hours < 24) return remainder ? `${hours}h ${remainder}m` : `${hours}h`;

  const days = Math.floor(hours / 24);
  return days === 1 ? '1 day' : `${days} days`;
}

// Waiting turns amber past 5 minutes and red past 15, so a queue that has
// been left alone is visible without reading any numbers.
function waitingUrgencyClass(isoString, status) {
  if (status !== 'WAITING') return 'text-creamMuted/70';
  const minutes = (Date.now() - new Date(isoString).getTime()) / 60000;
  if (minutes >= 15) return 'text-ember font-semibold';
  if (minutes >= 5) return 'text-brass font-semibold';
  return 'text-creamMuted';
}

// Timestamp of the last successful poll, shown next to the live indicator.
let lastConsoleSyncAt = null;
let consoleClockTimer = null;

function renderConsoleFreshness() {
  const label = document.getElementById('console-last-sync');
  if (!label) return;

  if (!lastConsoleSyncAt) {
    label.textContent = 'connecting';
    return;
  }

  const seconds = Math.floor((Date.now() - lastConsoleSyncAt) / 1000);
  label.textContent = seconds < 5 ? 'just now' : `${seconds}s ago`;

  // If polls stop landing, the number keeps climbing and the dot goes cold,
  // which is the director's first hint that the backend has gone away.
  const dot = document.getElementById('console-live-dot');
  if (dot) dot.classList.toggle('is-stale', seconds > 20);
}

// Rebuilds the chip row above the input. Called on every assistant message,
// and again when a consultant takes over or hands back, so the row reflects
// who the family is currently talking to.
function renderQuickChips() {
  const quickContainer = document.getElementById('chat-quick-actions');
  if (!quickContainer) return;

  quickContainer.innerHTML = '';
  const inHumanMode = state.conversationMode === 'HUMAN';

  getInitialDefaultOptions().forEach(opt => {
    if (opt.hideInHumanMode && inHumanMode) return;

    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = opt.accent ? CHIP_ACCENT_CLASS : CHIP_DEFAULT_CLASS;
    // Keep the id on the escalation chip so the existing delegated handler
    // and any external references still find it after a re-render.
    if (opt.accent) btn.id = 'btn-request-consultant';
    btn.innerHTML = opt.label;
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (opt.action) {
        opt.action();
      } else if (opt.text) {
        chatTextInput.value = opt.text;
        sendFreeChatMessage();
      }
    });
    quickContainer.appendChild(btn);
  });
}

