// A family arriving at 2am is in a different situation from one browsing on a
// weekday morning. Late at night the useful thing to lead with is that we can
// move tonight, not that we have packages to browse.
function buildGreeting() {
  const hour = new Date().getHours();
  if (hour >= 22 || hour < 6) return tr('greeting_night');
  if (hour < 12) return tr('greeting_morning');
  if (hour < 18) return tr('greeting_afternoon');
  return tr('greeting_evening');
}

// The questions families are afraid to ask, offered so they do not have to
// find the words. These are conversation openers, not navigation — the chips
// above the input already handle navigation.
const SUGGESTED_PROMPTS = [
  { label: 'My loved one has just passed', text: 'My loved one has just passed away. What do I need to do first?' },
  { label: 'What does a simple funeral cost?', text: 'What does a simple funeral cost?' },
  { label: 'What happens in the first 24 hours?', text: 'What happens in the first 24 hours after someone passes away?' },
  { label: 'I do not know where to start', text: 'I do not know where to start. Can you help me?' },
];

function appendSuggestedPrompts() {
  const wrap = document.createElement('div');
  wrap.className = 'suggested-prompts w-full flex flex-col gap-2 pt-1';

  const hint = document.createElement('div');
  hint.className = 'text-[10px] text-textMuted/80 font-semibold uppercase tracking-wider pl-1';
  hint.innerText = 'Or start with';
  wrap.appendChild(hint);

  const grid = document.createElement('div');
  grid.className = 'grid grid-cols-2 gap-2';

  SUGGESTED_PROMPTS.forEach(p => {
    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'text-left p-2.5 rounded-xl bg-bgPure border border-borderLight hover:border-primary hover:bg-fillColor text-[11px] leading-snug text-textDark font-semibold transition-all cursor-pointer';
    card.innerText = p.label;
    card.addEventListener('click', () => {
      // Clear the cards once used — they are a starting point, not a menu the
      // family should keep seeing mid-conversation.
      chatContainer.querySelectorAll('.suggested-prompts').forEach(el => el.remove());
      chatTextInput.value = p.text;
      sendFreeChatMessage();
    });
    grid.appendChild(card);
  });

  wrap.appendChild(grid);
  if (typingIndicator) {
    chatContainer.insertBefore(wrap, typingIndicator);
  } else {
    chatContainer.appendChild(wrap);
  }
}

function resetAndStartChat() {
  chatContainer.innerHTML = '';
  if (typingIndicator) chatContainer.appendChild(typingIndicator); // Keep indicator in DOM
  chatHistory = [];
  state.isStepByStepMode = false;
  lastMessageDateKey = null;
  lastBubbleSpeaker = null;
  handoffRuleShown = { joined: false, ended: false };

  const greeting = buildGreeting();
  const greetingBubble = appendBubble(greeting, 'ai');
  // Tag it so a later language switch can rewrite it in place. Without this
  // the greeting stays in whichever language was active when the chat first
  // opened, because setLanguage() does not re-render the message feed --
  // and it must not, since the family's own typed messages live there too.
  if (greetingBubble) {
    const el = greetingBubble.querySelector ? (greetingBubble.querySelector('[data-bubble-text]') || greetingBubble) : greetingBubble;
    el.setAttribute('data-greeting-bubble', '1');
  }
  chatHistory.push({ role: 'assistant', content: greeting });
  appendFirstLoadNote();

  updateStepOptionButtons(null);
  updateFormalHeaderProgress(null);
}

function isIntakeCompleteMessage(msg) {
  if (!msg) return false;
  const lower = msg.toLowerCase();
  return lower.includes('proceed to the planner') || lower.includes('we have everything we need') || lower.includes('arrangement finalized') || lower.includes('quote complete');
}

function appendPlannerButton() {
  chatContainer.querySelectorAll('.planner-cta-btn').forEach(el => el.remove());
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'planner-cta-btn w-full mt-3 p-3 bg-primary hover:bg-primaryHover text-white font-serif font-semibold text-sm rounded-xl transition-all shadow-md text-center cursor-pointer';
  btn.innerHTML = 'Go to Service & Cost Planner &rarr;';
  btn.addEventListener('click', () => {
    btn.remove();
    navigateTo('4');
  });
  if (typingIndicator) {
    chatContainer.insertBefore(btn, typingIndicator);
  } else {
    chatContainer.appendChild(btn);
  }
  scrollChatToBottom(true);
}

async function sendFreeChatMessage() {
  // Remove any previous unclicked button rows or planner CTA buttons when a new message is sent
  chatContainer.querySelectorAll('.escalation-buttons-container').forEach(el => el.remove());
  chatContainer.querySelectorAll('.step-options-wrapper').forEach(el => el.remove());
  chatContainer.querySelectorAll('.planner-cta-btn').forEach(el => el.remove());

  // Read once and reset immediately, so a click flag can never leak into the
  // next typed message.
  const wasOptionClick = state.pendingOptionSelection === true;
  state.pendingOptionSelection = false;
  if (chatTextInput.disabled) return;
  // maxlength on the input is a convenience, not a control — paste, autofill and
  // devtools all bypass it. Slice here as well, and the backend caps it again.
  const message = chatTextInput.value.trim().slice(0, MAX_MESSAGE_CHARS);
  if (!message) return;

  const msgLower = message.toLowerCase();
  if (msgLower.includes('step-by-step') || msgLower.includes('step by step') || msgLower.includes('guided setup') || msgLower.includes('start setup') || msgLower.includes('begin setup') || msgLower.includes('逐步引导') || msgLower.includes('开始向导') || msgLower.includes('panduan langkah demi langkah') || msgLower.includes('வழிகாட்டப்பட்ட') || msgLower.includes('படிப்படியான')) {
    state.isStepByStepMode = true;
    state.locationOfDeceased = null;
    state.religion = null;
    state.tier = null;
    state.casket = null;
    state.wakeDuration = null;
    state.addons = {};
    state.addons_asked_and_answered = false;
  }

  chatTextInput.value = '';
  if (window.resetChatInputHeight) window.resetChatInputHeight();
  chatTextInput.disabled = true;
  chatSendBtn.disabled = true;

  appendBubble(message, 'user');
  chatHistory.push({ role: 'user', content: message });

  if (typingIndicator) typingIndicator.classList.remove('hidden');
  requestAnimationFrame(() => {
    scrollChatToBottom(true);
  });

  // Handle active HUMAN Mode message routing
  if (state.consultantRequestId && state.conversationMode === 'HUMAN') {
    try {
      const resp = await fetch(`${API_BASE}/api/consultant-requests/${state.consultantRequestId}/customer-message`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: message, sender_name: state.user.name || "Customer" })
      });
      if (typingIndicator) typingIndicator.classList.add('hidden');
      if (resp.ok) {
        pollCustomerChat();
      }
    } catch (err) {
      console.error('Human mode message error:', err);
      if (typingIndicator) typingIndicator.classList.add('hidden');
    } finally {
      chatTextInput.disabled = false;
      chatSendBtn.disabled = false;
      chatTextInput.focus();
    }
    return;
  }

  let fetchSuccessful = false;
  try {
    // Remove any previous temporary error bubbles when sending a new message
    const oldErrors = chatContainer.querySelectorAll('.chat-error-bubble');
    oldErrors.forEach(el => el.remove());

    let data = null;
    let activeBubble = null;
    let textEl = null;
    let accumulatedText = '';

    const payloadBody = JSON.stringify({
      message: message,
      history: chatHistory,
      request_id: state.consultantRequestId,
      is_option_selection: wasOptionClick,
      user_id: (state.user && state.user.id) || null,
      customer_name: (state.user && !state.user.isGuest && state.user.name && state.user.name !== 'Guest Family') ? state.user.name : null,
      lang: state.currentLanguage || 'en'
    });


    try {
      const streamResponse = await fetch(`${API_BASE}/api/chat/stream`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: payloadBody
      });

      if (streamResponse.ok && streamResponse.body) {
        const reader = streamResponse.body.getReader();
        const decoder = new TextDecoder();
        let buffer = '';

        while (true) {
          const { value, done } = await reader.read();
          if (done) break;
          buffer += decoder.decode(value, { stream: true });
          const parts = buffer.split('\n\n');
          buffer = parts.pop();

          for (const part of parts) {
            const trimmed = part.trim();
            if (trimmed.startsWith('data: ')) {
              try {
                const packet = JSON.parse(trimmed.slice(6));
                if (packet.type === 'token') {
                  if (!activeBubble) {
                    if (typingIndicator) typingIndicator.classList.add('hidden');
                    activeBubble = appendBubble('', 'ai');
                    textEl = activeBubble.querySelector('div') || activeBubble.firstChild;
                  }
                  accumulatedText += packet.content;
                  if (textEl) {
                    textEl.innerHTML = formatChatMarkdown(accumulatedText);
                    maybeScrollChat(true);
                  }
                } else if (packet.type === 'done') {
                  data = packet;
                }
              } catch (parseErr) {}
            }
          }
        }
      }
    } catch (streamErr) {
      console.warn('[Chat Stream] Falling back to standard endpoint:', streamErr);
    }

    if (!data) {
      const response = await fetch(BACKEND_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: payloadBody
      });
      if (!response.ok) throw new Error('Backend unreachable');
      data = await response.json();
      if (!activeBubble) {
        if (typingIndicator) typingIndicator.classList.add('hidden');
        activeBubble = appendBubble(data.response, 'ai');
      }
    }

    fetchSuccessful = true;
    if (typingIndicator) typingIndicator.classList.add('hidden');

    if (activeBubble) {
      const textContainer = activeBubble.querySelector('div') || activeBubble.firstChild;
      if (textContainer && data.response) {
        textContainer.innerHTML = formatChatMarkdown(data.response);
      }
      if (!activeBubble.querySelector('.tts-play-btn')) {
        attachTTSButton(activeBubble, data.response);
      }
    }

    chatHistory.push({ role: 'assistant', content: data.response });
    updateStepOptionButtons(data.response, activeBubble);
    updateFormalHeaderProgress(data.response);


    if (data.needs_human) {
      appendEscalationButtons(activeBubble);
    }

    if (isIntakeCompleteMessage(data.response)) {
      state.isStepByStepMode = false;
      appendPlannerButton();
    }

    // A "go back" or "start over" removes answers. Only removals arrive in
    // `cleared` — `updates` carries values that are set, so without this the
    // planner kept showing a name or tier the chat had already dropped.
    if (Array.isArray(data.cleared) && data.cleared.length) {
      data.cleared.forEach(field => {
        if (field === "addons") {
          state.addons = {};
        } else if (field === "contactNumber") {
          if (state.user) state.user.contact = "";
        } else if (["tier", "religion", "casket", "wakeDuration"].includes(field)) {
          state[field] = null;
        } else if (state.coordination) {
          delete state.coordination[field];
        }
      });
    }

    // Synchronize chatbot selections with planner state dynamically
    if (data.updates) {
      if (data.updates.tier) state.tier = data.updates.tier;
      if (data.updates.religion) state.religion = data.updates.religion;
      if (data.updates.casket) state.casket = data.updates.casket;
      if (data.updates.wakeDuration) state.wakeDuration = data.updates.wakeDuration;
      if (data.updates.addons) {
        Object.keys(data.updates.addons).forEach(key => {
          state.addons[key] = data.updates.addons[key];
        });
      }
      if (data.updates.contactNumber) state.user.contact = data.updates.contactNumber;
      state.coordination = state.coordination || {};
      ["deceasedName", "locationOfDeceased", "nextOfKin", "dateOfPassing", "documentationStatus", "wakeLocation", "guestCount", "wakeStartDate", "paymentPreference", "repatriationNeeded"].forEach(field => {
        if (data.updates[field]) state.coordination[field] = data.updates[field];
      });
      if (typeof renderCoordinationSummary === 'function') {
        renderCoordinationSummary();
      }
      if (typeof renderPlannerSelectors === 'function') {
        renderPlannerSelectors();
      }
      if (typeof recalculatePlannerPrice === 'function') {
        recalculatePlannerPrice();
      }
    }

  } catch (error) {
    console.error('Integration Error:', error);
    if (typingIndicator) typingIndicator.classList.add('hidden');
    if (!fetchSuccessful) {
      const errBubble = appendBubble("I am having trouble connecting to my local server right now. Please check your Wi-Fi bridge.", 'ai');
      if (errBubble && errBubble.parentElement) {
        errBubble.parentElement.classList.add('chat-error-bubble');
      }
      // The message the family typed is gone from the input by this point. If
      // we do not offer it back they have to retype the whole thing, which is
      // the worst possible moment to ask that of someone.
      appendRetryButton(message, errBubble);
    }
  } finally {
    chatTextInput.disabled = false;
    chatSendBtn.disabled = false;
    chatTextInput.focus();
  }
}

function appendRetryButton(failedMessage, errBubble) {
  const wrapper = document.createElement('div');
  wrapper.className = 'chat-error-bubble flex justify-start w-full mt-1';

  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'px-3 py-1.5 rounded-xl bg-fillColor hover:bg-highlight/40 text-textDark border border-highlight text-[11px] font-semibold transition-all cursor-pointer';
  btn.innerText = 'Retry';
  btn.setAttribute('aria-label', 'Send that message again');
  btn.addEventListener('click', () => {
    // Drop the failed user bubble and the error, then resend, so the feed does
    // not accumulate a trail of failed attempts.
    chatContainer.querySelectorAll('.chat-error-bubble').forEach(el => el.remove());
    if (chatHistory.length && chatHistory[chatHistory.length - 1].role === 'user') {
      chatHistory.pop();
    }
    const bubbles = chatContainer.querySelectorAll('.flex.justify-end');
    if (bubbles.length) bubbles[bubbles.length - 1].remove();
    chatTextInput.value = failedMessage;
    sendFreeChatMessage();
  });

  wrapper.appendChild(btn);
  if (typingIndicator) {
    chatContainer.insertBefore(wrapper, typingIndicator);
  } else {
    chatContainer.appendChild(wrapper);
  }
}

if (chatSendBtn && chatTextInput) {
  chatSendBtn.addEventListener('click', sendFreeChatMessage);

  // Enter sends; Shift+Enter inserts a newline, which is why the field is now a
  // textarea rather than an input.
  chatTextInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendFreeChatMessage();
    }
  });

  // Auto-grow: the field starts one line tall and grows with the message up to
  // the max-height set in CSS, then scrolls. Resetting to auto first lets it
  // shrink again when text is deleted.
  const autoGrow = () => {
    chatTextInput.style.height = 'auto';
    chatTextInput.style.height = Math.max(44, Math.min(chatTextInput.scrollHeight, 128)) + 'px';
  };
  chatTextInput.addEventListener('input', autoGrow);
  window.resetChatInputHeight = () => { chatTextInput.style.height = '44px'; };

  // The + button reveals the quick actions, which are hidden by default so the
  // chat keeps that strip of space. The icon rotates to an x while open.
  const actionsToggle = document.getElementById('chat-actions-toggle');
  const actionsRow = document.getElementById('chat-quick-actions');
  const actionsIcon = document.getElementById('chat-actions-icon');
  if (actionsToggle && actionsRow) {
    actionsToggle.addEventListener('click', () => {
      const open = actionsRow.classList.toggle('open');
      actionsToggle.setAttribute('aria-expanded', String(open));
      if (actionsIcon) actionsIcon.style.transform = open ? 'rotate(45deg)' : 'rotate(0deg)';
    });
    // Tapping a chip closes the tray again with smooth transition.
    actionsRow.addEventListener('click', (e) => {
      if (e.target.closest('.quick-chip')) {
        actionsRow.classList.remove('open');
        actionsToggle.setAttribute('aria-expanded', 'false');
        if (actionsIcon) actionsIcon.style.transform = 'rotate(0deg)';
      }
    });
  }

  // High-Accuracy Speech-to-Text Voice Dictation with Local Whisper AI & WebSpeech
  const micBtn = document.getElementById('chat-mic-btn');
  if (micBtn && chatTextInput) {
    let mediaRecorder = null;
    let audioChunks = [];
    let isListening = false;
    let prefixBeforeDictation = '';
    let recognitionFallback = null;

    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;

    const startListening = async () => {
      stopCurrentSpeech();
      prefixBeforeDictation = chatTextInput.value ? chatTextInput.value.trim() : '';

      // Priority 1: High-Definition Audio Recording streamed to Local Whisper AI
      if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia && window.MediaRecorder) {
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          audioChunks = [];
          
          let mimeType = 'audio/webm';
          if (!MediaRecorder.isTypeSupported('audio/webm')) {
            if (MediaRecorder.isTypeSupported('audio/mp4')) mimeType = 'audio/mp4';
            else if (MediaRecorder.isTypeSupported('audio/aac')) mimeType = 'audio/aac';
          }

          mediaRecorder = mimeType ? new MediaRecorder(stream, { mimeType }) : new MediaRecorder(stream);

          mediaRecorder.ondataavailable = (e) => {
            if (e.data && e.data.size > 0) audioChunks.push(e.data);
          };

          mediaRecorder.onstop = async () => {
            stream.getTracks().forEach(t => t.stop());
            const ext = mimeType.includes('mp4') ? '.mp4' : '.webm';
            const audioBlob = new Blob(audioChunks, { type: mimeType || 'audio/webm' });
            
            if (audioBlob.size < 500) {
              chatTextInput.placeholder = 'Type your message...';
              return;
            }

            chatTextInput.placeholder = 'Transcribing with Whisper AI...';
            const formData = new FormData();
            formData.append('file', audioBlob, `voice_recording${ext}`);

            try {
              const resp = await fetch(`${API_BASE}/api/transcribe`, {
                method: 'POST',
                body: formData
              });
              if (resp.ok) {
                const data = await resp.json();
                if (data.success && data.transcript) {
                  const prefix = prefixBeforeDictation ? prefixBeforeDictation + ' ' : '';
                  chatTextInput.value = prefix + data.transcript.trim();
                  autoGrow();
                  chatTextInput.dispatchEvent(new Event('input'));
                }
              }
            } catch (err) {
              console.warn('[Whisper] API transcribe error:', err);
            } finally {
              chatTextInput.placeholder = 'Type your message...';
            }
          };

          mediaRecorder.start(250);
          isListening = true;
          micBtn.classList.add('listening');
          chatTextInput.placeholder = 'Listening... Speak and tap mic when done';
          return;
        } catch (err) {
          console.warn('getUserMedia error, trying SpeechRecognition:', err);
        }
      }

      // Priority 2: Web Speech API fallback
      if (SpeechRecognition) {
        try {
          if (!recognitionFallback) {
            recognitionFallback = new SpeechRecognition();
            recognitionFallback.continuous = false;
            recognitionFallback.interimResults = true;
            recognitionFallback.lang = 'en-SG';
          }

          let accumulatedFinal = '';
          recognitionFallback.onresult = (event) => {
            let interimTranscript = '';
            for (let i = event.resultIndex; i < event.results.length; ++i) {
              if (event.results[i].isFinal) {
                const piece = event.results[i][0].transcript.trim();
                if (piece) accumulatedFinal = accumulatedFinal ? `${accumulatedFinal} ${piece}` : piece;
              } else {
                interimTranscript += event.results[i][0].transcript;
              }
            }
            const currentSpoken = (accumulatedFinal + (interimTranscript ? (accumulatedFinal ? ' ' : '') + interimTranscript : '')).trim();
            const fullMessage = (prefixBeforeDictation ? `${prefixBeforeDictation} ` : '') + currentSpoken;
            if (fullMessage) {
              chatTextInput.value = fullMessage;
              autoGrow();
              chatTextInput.dispatchEvent(new Event('input'));
            }
          };

          recognitionFallback.onend = () => {
            isListening = false;
            micBtn.classList.remove('listening');
            chatTextInput.placeholder = 'Type your message...';
          };

          recognitionFallback.onerror = (e) => {
            console.warn('[Speech] Error:', e.error);
            isListening = false;
            micBtn.classList.remove('listening');
            chatTextInput.placeholder = 'Type your message...';
          };

          recognitionFallback.start();
          isListening = true;
          micBtn.classList.add('listening');
          chatTextInput.placeholder = 'Listening... Speak now';
          return;
        } catch (e) {
          console.warn('[Speech] Recognition start error:', e);
        }
      }

      chatTextInput.placeholder = 'Please open via https:// on mobile for mic';
      setTimeout(() => { chatTextInput.placeholder = 'Type your message...'; }, 2500);
    };

    const stopListening = () => {
      if (mediaRecorder && mediaRecorder.state !== 'inactive') {
        try { mediaRecorder.stop(); } catch (e) {}
      }
      if (recognitionFallback) {
        try { recognitionFallback.stop(); } catch (e) {}
      }
      isListening = false;
      micBtn.classList.remove('listening');
      chatTextInput.placeholder = 'Type your message...';
    };

    micBtn.addEventListener('click', (e) => {
      e.preventDefault();
      if (isListening) {
        stopListening();
      } else {
        startListening();
      }
    });
  }

  // Character counter. Hidden until the family is close to the cap — a counter
  // on an empty box is noise, but hitting maxlength with no warning just feels
  // like the keyboard stopped working.
  const charCount = document.getElementById('chat-char-count');
  if (charCount) {
    const WARN_AT = Math.floor(MAX_MESSAGE_CHARS * 0.8);
    chatTextInput.addEventListener('input', () => {
      const len = chatTextInput.value.length;
      if (len < WARN_AT) {
        charCount.classList.add('hidden');
        return;
      }
      charCount.classList.remove('hidden');
      charCount.textContent = `${len}/${MAX_MESSAGE_CHARS}`;
      charCount.style.color = len >= MAX_MESSAGE_CHARS ? '#C8553D' : '#B8860B';
    });
  }
}

