function escapeHtml(str) {
  const div = document.createElement('div');
  div.textContent = str;
  return div.innerHTML;
}

function renderCoordinationSummary() {
  if (!coordinationSummaryCard || !coordinationSummaryList) return;
  const c = state.coordination || {};
  const labels = {
    deceasedName: 'Departed Loved One',
    locationOfDeceased: 'Currently Resting At',
    nextOfKin: 'Next of Kin / Authorised',
    dateOfPassing: 'Date of Passing',
    documentationStatus: 'Death Certificate Ready',
    wakeLocation: 'Wake Location',
    guestCount: 'Expected Guests',
    wakeStartDate: 'Wake Start Date',
    paymentPreference: 'Payment Preference',
    repatriationNeeded: 'Repatriation Needed',
  };
  const valueDisplay = {
    paymentPreference: { installment: 'Installment Plan', full: 'Full Payment' },
    repatriationNeeded: { yes: 'Yes', no: 'No' },
    nextOfKin: { yes: 'Yes', no: 'No — helping on behalf' },
    documentationStatus: { yes: 'Yes', no: 'Not yet — assistance needed' },
  };

  const entries = Object.keys(labels).filter(key => c[key]);
  if (entries.length === 0) {
    coordinationSummaryCard.classList.add('hidden');
    return;
  }

    coordinationSummaryCard.classList.remove('hidden');
  coordinationSummaryList.innerHTML = entries.map(key => {
    const rawValue = String(c[key]);
    const mapped = (valueDisplay[key] && valueDisplay[key][rawValue.toLowerCase()]) || rawValue;
    const displayText = mapped.charAt(0).toUpperCase() + mapped.slice(1);
    return `
      <div class="flex justify-between items-start gap-3 text-xs">
        <span class="text-textMuted font-medium flex-shrink-0">${escapeHtml(labels[key])}</span>
        <span class="text-textDark text-right">${escapeHtml(displayText)}</span>
      </div>
    `;
  }).join('');
}

