// Helper to get thumbnail image for any planner item
function getItemImage(category, key) {
  const normCat = normalizeCategory(category);
  const item = (PRODUCT_CATALOG_DETAILS[normCat] && PRODUCT_CATALOG_DETAILS[normCat][key]) ||
               (PRODUCT_CATALOG_DETAILS[category] && PRODUCT_CATALOG_DETAILS[category][key]);
  if (item && item.image) return item.image;
  return "https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&w=600&q=80";
}

