let drawing = false;
let ctx = null;

function syncPDFSignature() {
  const pdfSignatureImage = document.getElementById('pdf-signature-image');
  const pdfSignaturePlaceholder = document.getElementById('pdf-signature-placeholder');
  const pdfSignatureStatus = document.getElementById('pdf-signature-status');
  const pdfSignerName = document.getElementById('pdf-signer-name');
  const pdfSignerDate = document.getElementById('pdf-signer-date');
  const pdfSignerVerification = document.getElementById('pdf-signer-verification');

  if (state.hasSignature && canvas) {
    try {
      const dataUrl = canvas.toDataURL();
      state.savedSignatureDataUrl = dataUrl;
      if (state.quoteId) {
        const activeDraft = state.drafts.find(d => d.id === state.quoteId);
        if (activeDraft) activeDraft.signatureDataUrl = dataUrl;
      }
      if (pdfSignatureImage) {
        pdfSignatureImage.src = dataUrl;
        pdfSignatureImage.classList.remove('hidden');
      }
      if (pdfSignaturePlaceholder) pdfSignaturePlaceholder.classList.add('hidden');
      if (pdfSignatureStatus) {
        pdfSignatureStatus.textContent = 'EXECUTED & VERIFIED';
        pdfSignatureStatus.className = 'text-[8px] font-bold px-2 py-0.5 rounded bg-primary/10 text-primary border border-primary/30';
      }
      if (pdfSignerName) pdfSignerName.textContent = state.user.name || "Guest Family";
      const displayTimestamp = state.signedTimestamp || state.timestamp || new Date().toLocaleString();
      if (pdfSignerDate) pdfSignerDate.textContent = displayTimestamp;
      if (pdfSignerVerification) pdfSignerVerification.classList.remove('hidden');
    } catch (e) {
      console.warn('Signature sync error:', e);
    }
  } else if (state.savedSignatureDataUrl) {
    if (pdfSignatureImage) {
      pdfSignatureImage.src = state.savedSignatureDataUrl;
      pdfSignatureImage.classList.remove('hidden');
    }
    if (pdfSignaturePlaceholder) pdfSignaturePlaceholder.classList.add('hidden');
    if (pdfSignatureStatus) {
      pdfSignatureStatus.textContent = 'EXECUTED & VERIFIED';
      pdfSignatureStatus.className = 'text-[8px] font-bold px-2 py-0.5 rounded bg-primary/10 text-primary border border-primary/30';
    }
    if (pdfSignerName) pdfSignerName.textContent = state.user.name || "Guest Family";
    const displayTimestamp = state.signedTimestamp || state.timestamp || new Date().toLocaleString();
    if (pdfSignerDate) pdfSignerDate.textContent = displayTimestamp;
    if (pdfSignerVerification) pdfSignerVerification.classList.remove('hidden');
  } else {
    if (pdfSignatureImage) {
      pdfSignatureImage.src = '';
      pdfSignatureImage.classList.add('hidden');
    }
    if (pdfSignaturePlaceholder) pdfSignaturePlaceholder.classList.remove('hidden');
    if (pdfSignatureStatus) {
      pdfSignatureStatus.textContent = 'PENDING SIGNATURE';
      pdfSignatureStatus.className = 'text-[8px] font-semibold px-2 py-0.5 rounded bg-fillColor text-textMuted border border-borderLight';
    }
    if (pdfSignerName) pdfSignerName.textContent = state.user.name || "Guest Family";
    if (pdfSignerDate) pdfSignerDate.textContent = 'Pending';
    if (pdfSignerVerification) pdfSignerVerification.classList.add('hidden');
  }
}

function setupSignaturePad() {
  ctx = canvas.getContext('2d');
  ctx.strokeStyle = '#2D1A12';
  ctx.lineWidth = 2.5;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  canvas.addEventListener('mousedown', (e) => {
    drawing = true;
    canvasLabelHint.style.opacity = '0';
    ctx.beginPath();
    const rect = canvas.getBoundingClientRect();
    ctx.moveTo(e.clientX - rect.left, e.clientY - rect.top);
  });

  canvas.addEventListener('mousemove', (e) => {
    if (!drawing) return;
    const rect = canvas.getBoundingClientRect();
    ctx.lineTo(e.clientX - rect.left, e.clientY - rect.top);
    ctx.stroke();
    state.hasSignature = true;
    syncPDFSignature();
  });

  canvas.addEventListener('mouseup', () => {
    drawing = false;
    ctx.closePath();
    state.hasSignature = true;
    const now = new Date();
    state.signedTimestamp = now.toLocaleDateString('en-SG', { day: '2-digit', month: 'short', year: 'numeric' }) + ' ' + now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    state.timestamp = state.signedTimestamp;
    state.savedSignatureDataUrl = canvas.toDataURL();
    syncPDFSignature();
  });

  canvas.addEventListener('mouseleave', () => {
    if (drawing) {
      drawing = false;
      ctx.closePath();
      state.savedSignatureDataUrl = canvas.toDataURL();
      syncPDFSignature();
    }
  });

  canvas.addEventListener('touchstart', (e) => {
    const touch = e.touches[0];
    const rect = canvas.getBoundingClientRect();
    drawing = true;
    canvasLabelHint.style.opacity = '0';
    ctx.beginPath();
    ctx.moveTo(touch.clientX - rect.left, touch.clientY - rect.top);
    e.preventDefault();
  }, { passive: false });

  canvas.addEventListener('touchmove', (e) => {
    if (!drawing) return;
    const touch = e.touches[0];
    const rect = canvas.getBoundingClientRect();
    ctx.lineTo(touch.clientX - rect.left, touch.clientY - rect.top);
    ctx.stroke();
    state.hasSignature = true;
    syncPDFSignature();
    e.preventDefault();
  }, { passive: false });

  canvas.addEventListener('touchend', () => {
    drawing = false;
    ctx.closePath();
    state.hasSignature = true;
    const now = new Date();
    state.signedTimestamp = now.toLocaleDateString('en-SG', { day: '2-digit', month: 'short', year: 'numeric' }) + ' ' + now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    state.timestamp = state.signedTimestamp;
    state.savedSignatureDataUrl = canvas.toDataURL();
    syncPDFSignature();
  });
}

function resizeSignatureCanvas() {
  const container = document.getElementById('canvas-container');
  if (!container || !canvas) return;

  const w = container.clientWidth;
  const h = container.clientHeight;
  if (w === 0 || h === 0) return;

  // Preserve existing signature image if available
  const existingSig = state.savedSignatureDataUrl || (state.hasSignature ? canvas.toDataURL() : null);

  canvas.width = w;
  canvas.height = h;

  ctx = canvas.getContext('2d');
  ctx.strokeStyle = '#2D1A12';
  ctx.lineWidth = 2.4;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  if (existingSig) {
    state.savedSignatureDataUrl = existingSig;
    state.hasSignature = true;
    canvasLabelHint.style.opacity = '0';
    const img = new Image();
    img.onload = () => {
      ctx.drawImage(img, 0, 0, w, h);
      syncPDFSignature();
    };
    img.src = existingSig;
  } else {
    state.hasSignature = false;
    canvasLabelHint.style.opacity = '1';
    syncPDFSignature();
  }
}

btnClearCanvas.addEventListener('click', () => {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  state.hasSignature = false;
  state.savedSignatureDataUrl = null;
  canvasLabelHint.style.opacity = '1';
  syncPDFSignature();
});

// When the family signs off on an arrangement, raise a consultant ticket
// so the signed order lands in the staff console with a full briefing
// instead of the director only being told about it in the mock notification.
// The login field takes a phone number or an email, so the signed-arrangement
// ticket must not file an email address as the family's phone number.
function contactLooksLikeEmail() {
  const contact = String((state.user && state.user.contact) || '').trim();
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact);
}

async function raiseTicketForSignedArrangement() {
  // Guard: one ticket per signed arrangement, even if the button is double-clicked.
  if (state.signedTicketPending) return;
  state.signedTicketPending = true;

  try {
    const resp = await fetch(`${API_BASE}/api/consultant-requests`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        customer_name: (state.user && state.user.name) || 'Guest Family',
        phone: contactLooksLikeEmail() ? 'Not provided' : ((state.user && state.user.contact) || 'Not provided'),
        email: (state.user && state.user.email) || (contactLooksLikeEmail() ? state.user.contact : ''),
        preferred_contact_method: 'Phone call',
        preferred_contact_time: 'Immediate',
        reason: `Signed arrangement ${state.quoteId} — awaiting director confirmation`,
        history: chatHistory,
        intake_state: state,
        user_id: (state.user && state.user.id) || null
      })
    });

    if (!resp.ok) throw new Error('Failed to raise consultant ticket');
    const data = await resp.json();

    state.consultantRequestId = data.request_id;
    // Listen for the consultant taking over, so their replies arrive in chat.
    startCustomerPolling();
  } catch (err) {
    // The family already sees the success screen; a failed ticket must not
    // undo that, so this only logs and lets them retry via the chat.
    console.error('Could not raise consultant ticket for signed arrangement:', err);
    state.signedTicketPending = false;
  }
}

