async function checkBackendStatus() {
  const dotEl = document.getElementById('header-status-dot');
  try {
    const res = await fetch(STATUS_URL);
    if (res.ok) {
      if (dotEl) {
        dotEl.classList.remove('bg-gray-400', 'bg-red-500');
        dotEl.classList.add('bg-successColor');
        dotEl.title = 'Backend Online';
      }
    } else if (dotEl) {
      dotEl.classList.remove('bg-successColor');
      dotEl.classList.add('bg-gray-400');
      dotEl.title = 'Backend Offline';
    }
  } catch (err) {
    if (dotEl) {
      dotEl.classList.remove('bg-successColor');
      dotEl.classList.add('bg-gray-400');
      dotEl.title = 'Backend Unreachable';
    }
  }
}

async function loadCatalogData() {
  try {
    const response = await fetch(`${API_BASE}/api/catalog`);
    if (!response.ok) throw new Error('Catalog request failed');
    const data = await response.json();

    // Map backend JSON to pricingConfig
    if (data.servicePackages) {
      pricingConfig.tiers = {};
      data.servicePackages.forEach(p => {
        pricingConfig.tiers[p.id] = { name: p.name, price: p.price, desc: p.description };
      });
    }
    if (data.religiousCeremonies) {
      pricingConfig.religions = {};
      data.religiousCeremonies.forEach(r => {
        pricingConfig.religions[r.id] = { name: r.name, price: r.price, desc: r.description };
      });
    }
    if (data.casketUpgrades) {
      pricingConfig.caskets = {};
      data.casketUpgrades.forEach(c => {
        pricingConfig.caskets[c.id] = { name: c.name, price: c.price };
      });
    }
    if (data.wakeDurations) {
      pricingConfig.durations = {};
      data.wakeDurations.forEach(d => {
        pricingConfig.durations[d.id] = { name: d.name, price: d.price, days: d.days };
      });
    }
    if (data.logisticsAndAddons) {
      pricingConfig.addons = {};
      data.logisticsAndAddons.forEach(a => {
        if (a.pricingType === 'per_day') {
          pricingConfig.addons[a.id] = { name: a.name, pricePerDay: a.price, desc: a.description };
        } else {
          pricingConfig.addons[a.id] = { name: a.name, priceFlat: a.price, desc: a.description };
        }
      });
    }
    console.log('Successfully loaded catalog data from backend database');
  } catch (error) {
    console.warn('Could not load dynamic catalog from database, using offline defaults:', error);
  } finally {
    // Force UI refresh after load or fallback complete
    recalculatePlannerPrice();
    checkBackendStatus();
  }
}

