async function downloadFormalPDF() {
  const sheet = document.getElementById('formal-pdf-sheet');
  if (!sheet) return;

  const btnModalDownloadPdf = document.getElementById('btn-modal-download-pdf');
  const originalText = btnModalDownloadPdf ? btnModalDownloadPdf.querySelector('span').textContent : '';
  if (btnModalDownloadPdf) btnModalDownloadPdf.querySelector('span').textContent = 'Generating PDF...';

  const filename = `Solace_Dignity_Care_Quote_${state.quoteId || 'QT-9812A'}.pdf`;

  // Create a clean, unclipped off-screen clone specifically for high-res A4 PDF rendering
  const cloneWrapper = document.createElement('div');
  cloneWrapper.style.position = 'absolute';
  cloneWrapper.style.left = '-9999px';
  cloneWrapper.style.top = '0';
  cloneWrapper.style.width = '800px';
  cloneWrapper.style.backgroundColor = '#ffffff';
  cloneWrapper.style.boxSizing = 'border-box';
  cloneWrapper.style.zIndex = '-9999';

  const clone = sheet.cloneNode(true);
  clone.classList.remove('max-w-lg');
  clone.style.width = '800px';
  clone.style.maxWidth = '800px';
  clone.style.boxSizing = 'border-box';
  clone.style.maxHeight = 'none';
  clone.style.overflow = 'visible';
  clone.style.boxShadow = 'none';
  clone.style.border = 'none';
  clone.style.margin = '0';
  clone.style.padding = '36px';

  cloneWrapper.appendChild(clone);
  document.body.appendChild(cloneWrapper);

  try {
    // Priority 1: jsPDF + html2canvas for 100% precision full A4 page width scaling (210mm)
    if (typeof html2canvas !== 'undefined' && (window.jspdf || window.jsPDF)) {
      const canvas = await html2canvas(clone, {
        scale: 2.5,
        useCORS: true,
        allowTaint: true,
        logging: false,
        width: 800,
        windowWidth: 800,
        scrollY: 0
      });
      if (document.body.contains(cloneWrapper)) document.body.removeChild(cloneWrapper);

      const imgData = canvas.toDataURL('image/jpeg', 0.98);
      const JSClass = (window.jspdf && window.jspdf.jsPDF) ? window.jspdf.jsPDF : window.jsPDF;
      const pdf = new JSClass('p', 'mm', 'a4');
      const pdfWidth = pdf.internal.pageSize.getWidth(); // 210mm (100% full page width)
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width; // Proportional height in mm

      pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight);
      pdf.save(filename);

      if (btnModalDownloadPdf) btnModalDownloadPdf.querySelector('span').textContent = 'PDF File Downloaded!';
      setTimeout(() => {
        if (btnModalDownloadPdf) btnModalDownloadPdf.querySelector('span').textContent = originalText;
      }, 2000);
      return;
    }

    // Priority 2: html2pdf bundle
    if (typeof html2pdf !== 'undefined') {
      const opt = {
        margin: 0,
        filename: filename,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2.5, useCORS: true, allowTaint: true, logging: false, windowWidth: 800, scrollY: 0 },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      await html2pdf().set(opt).from(clone).save();
      if (document.body.contains(cloneWrapper)) document.body.removeChild(cloneWrapper);

      if (btnModalDownloadPdf) btnModalDownloadPdf.querySelector('span').textContent = 'PDF File Downloaded!';
      setTimeout(() => {
        if (btnModalDownloadPdf) btnModalDownloadPdf.querySelector('span').textContent = originalText;
      }, 2000);
      return;
    }
  } catch (err) {
    console.warn('PDF export error:', err);
    if (document.body.contains(cloneWrapper)) document.body.removeChild(cloneWrapper);
  }

  if (btnModalDownloadPdf) btnModalDownloadPdf.querySelector('span').textContent = originalText;
}

function generateCanvasPdfFile(sheet, filename, btn, originalText) {
  if (typeof html2canvas !== 'undefined') {
    html2canvas(sheet, { scale: 2 }).then(canvas => {
      canvas.toBlob(blob => {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      }, 'image/jpeg', 0.95);
    });
  } else {
    const htmlContent = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${filename}</title><script src="https://cdn.tailwindcss.com"></script></head><body class="p-8 bg-slate-100">${sheet.outerHTML}</body></html>`;
    const blob = new Blob([htmlContent], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  if (btn) btn.querySelector('span').textContent = 'PDF Downloaded!';
  setTimeout(() => {
    if (btn) btn.querySelector('span').textContent = originalText;
  }, 2000);
}

