if (btnCopyObituary) {
  btnCopyObituary.addEventListener('click', () => {
    const obitBox = document.getElementById('obituary-preview-box');
    if (obitBox) {
      navigator.clipboard.writeText(obitBox.textContent).then(() => {
        const originalText = btnCopyObituary.querySelector('span').textContent;
        btnCopyObituary.querySelector('span').textContent = 'Copied!';
        setTimeout(() => {
          btnCopyObituary.querySelector('span').textContent = originalText;
        }, 2000);
      }).catch(err => {
        console.error('Failed to copy text: ', err);
      });
    }
  });
}

function updateObituaryDraft() {
  const deceasedName = (state.coordination && state.coordination.deceasedName) || "our beloved";
  const tierObj = (state.tier && pricingConfig.tiers[state.tier]) || pricingConfig.tiers.standard;
  const durObj = (state.wakeDuration && pricingConfig.durations[state.wakeDuration]) || null;
  const tierName = tierObj ? tierObj.name : "Standard Service Tier";
  const durName = durObj ? durObj.name : "To be confirmed";
  const dateStr = new Date().toLocaleDateString('en-US', { day: 'numeric', month: 'long', year: 'numeric' });

  const draftText = `In loving memory of ${deceasedName}, whose life we celebrate and cherish. A memorial service has been arranged in coordination with Solace Dignity Care on ${dateStr}.\n\nDetails of the arrangement:\n- Service Tier: ${tierName}\n- Wake Duration: ${durName}\n\nWe appreciate the prayers and support of family and friends during this sensitive period. May they rest in eternal peace.\n\nFamily Contact: ${state.user.contact || "Provided during consultation"}`;

  const obitBox = document.getElementById('obituary-preview-box');
  if (obitBox) {
    obitBox.textContent = draftText;
  }
}

