// Translate a spec label or category name. Unknown strings pass through
// unchanged rather than becoming a raw key.
function trDetail(text, table) {
  const lang = (state && state.currentLanguage) || 'en';
  if (lang === 'en' || !text) return text;
  const entry = table[text];
  return (entry && entry[lang]) || text;
}

