let currentPreviewItem = null;

function normalizeCategory(category) {
  if (!category) return 'tiers';
  const c = category.toLowerCase();
  if (c === 'tier' || c === 'tiers') return 'tiers';
  if (c === 'religion' || c === 'religions') return 'religions';
  if (c === 'location' || c === 'locations' || c === 'wakelocation') return 'locations';
  if (c === 'duration' || c === 'durations' || c === 'wakeduration') return 'durations';
  if (c === 'casket' || c === 'caskets') return 'caskets';
  if (c === 'ash' || c === 'ashmanagement') return 'ashManagement';
  if (c === 'addon' || c === 'addons') return 'addons';
  return category;
}

function openProductPreviewModal(rawCategory, rawKey) {
  const normCat = normalizeCategory(rawCategory);
  let itemData = (PRODUCT_CATALOG_DETAILS[normCat] && PRODUCT_CATALOG_DETAILS[normCat][rawKey]) ||
                 (PRODUCT_CATALOG_DETAILS[rawCategory] && PRODUCT_CATALOG_DETAILS[rawCategory][rawKey]);

  // If not found directly, check aliases
  if (!itemData) {
    const aliasMap = {
      'direct': 'direct_cremation',
      'eco': 'standard',
      'garden_of_peace': 'inland',
      'sea_burial': 'sea',
      'tentage': 'actent',
      'video': 'memory',
      'hearse': 'mitsuoka_hearse',
      'floral': 'wreaths'
    };
    const mappedKey = aliasMap[rawKey] || Object.keys(aliasMap).find(k => aliasMap[k] === rawKey);
    if (mappedKey) {
      itemData = (PRODUCT_CATALOG_DETAILS[normCat] && PRODUCT_CATALOG_DETAILS[normCat][mappedKey]) ||
                 (PRODUCT_CATALOG_DETAILS[rawCategory] && PRODUCT_CATALOG_DETAILS[rawCategory][mappedKey]);
    }
  }

  // Graceful fallback from pricingConfig if still not found
  if (!itemData) {
    const configGroup = pricingConfig[normCat] || pricingConfig[rawCategory];
    const configItem = configGroup && configGroup[rawKey];
    if (configItem) {
      let priceStr = 'Included';
      if (configItem.price > 0) priceStr = `$${configItem.price.toLocaleString()}`;
      else if (configItem.priceFlat > 0) priceStr = `+$${configItem.priceFlat.toLocaleString()} ${tr('price_unit_flat', 'flat')}`;
      else if (configItem.pricePerDay > 0) priceStr = `+$${configItem.pricePerDay}${tr('price_unit_per_day', '/day')}`;

      itemData = {
        category: normCat.toUpperCase(),
        title: configItem.name || rawKey,
        subtitle: configItem.desc || "Verified ceremonial option",
        price: priceStr,
        image: "https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&w=800&q=80",
        desc: configItem.desc || "Comprehensive memorial arrangement curated in accordance with Singapore regulations and family traditions.",
        specs: [
          { label: "Option", value: configItem.name || rawKey },
          { label: "Price Structure", value: priceStr },
          { label: "Compliance", value: "NEA & MOH Approved" },
          { label: "Coordination", value: "Dedicated Director" }
        ],
        inclusions: [
          "Itemized and certified under Solace Dignity Care 2026 price list",
          "Dedicated on-site assistance and coordination",
          "Transparent pricing with no hidden surcharges"
        ]
      };
    }
  }

  if (!itemData) return;
  currentPreviewItem = { category: normCat, key: rawKey, itemData };

  const modal = document.getElementById('product-preview-modal');
  const sheet = document.getElementById('product-preview-sheet');
  const catBadge = document.getElementById('preview-category-badge');
  const priceBadge = document.getElementById('preview-price-badge');
  const img = document.getElementById('preview-image');
  const title = document.getElementById('preview-title');
  const subtitle = document.getElementById('preview-subtitle');
  const desc = document.getElementById('preview-desc');
  const specsGrid = document.getElementById('preview-specs-grid');
  const inclusionsList = document.getElementById('preview-inclusions-list');
  const selectBtnText = document.getElementById('preview-select-btn-text');

  if (catBadge) catBadge.textContent = trDetail(itemData.category, PRODUCT_DETAIL_CATEGORIES) || "Details";
  if (priceBadge) priceBadge.textContent = itemData.price || "";
  if (img) {
    img.src = itemData.image;
    img.alt = itemData.title;
  }
  const locObj = getLocalizedCatalogItem(normCat, rawKey, itemData.title, itemData.subtitle);
  const locTitle = locObj.name !== itemData.title ? locObj.name : locItemName(itemData.title);
  const locSub = locObj.desc !== itemData.subtitle ? locObj.desc : itemData.subtitle;

  if (title) title.textContent = locTitle;
  if (subtitle) subtitle.textContent = locSub;
  if (desc) desc.textContent = itemData.desc;

  if (specsGrid) {
    specsGrid.innerHTML = (itemData.specs || []).map(s => `
      <div class="bg-bgPure p-2 rounded-lg border border-borderLight/60">
        <div class="text-[9px] uppercase tracking-wider text-textMuted font-bold">${escapeHtml(trDetail(s.label, PRODUCT_DETAIL_LABELS))}</div>
        <div class="text-xs font-semibold text-textDark mt-0.5">${escapeHtml(s.value)}</div>
      </div>
    `).join('');
  }

  if (inclusionsList) {
    inclusionsList.innerHTML = (itemData.inclusions || []).map(inc => `
      <li class="flex items-start gap-2">
        <svg class="w-3.5 h-3.5 text-primary shrink-0 mt-0.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
        <span class="leading-snug">${escapeHtml(inc)}</span>
      </li>
    `).join('');
  }

  // Check if currently selected in planner state
  let isCurrentlySelected = false;
  if (normCat === 'tiers') isCurrentlySelected = state.tier === rawKey;
  else if (normCat === 'religions') isCurrentlySelected = state.religion === rawKey;
  else if (normCat === 'locations') isCurrentlySelected = state.wakeLocation === rawKey;
  else if (normCat === 'durations') isCurrentlySelected = state.wakeDuration === rawKey;
  else if (normCat === 'caskets') isCurrentlySelected = state.casket === rawKey;
  else if (normCat === 'ashManagement') isCurrentlySelected = state.ashManagement === rawKey;
  else if (normCat === 'addons') isCurrentlySelected = !!state.addons[rawKey];

  if (selectBtnText) {
    selectBtnText.textContent = isCurrentlySelected ? "Currently Selected" : "Select This Option";
  }

  if (modal && sheet) {
    modal.classList.remove('opacity-0', 'pointer-events-none');
    requestAnimationFrame(() => requestAnimationFrame(() => {
      sheet.classList.remove('translate-y-full');
    }));
  }
}

function closeProductPreviewModal() {
  const modal = document.getElementById('product-preview-modal');
  const sheet = document.getElementById('product-preview-sheet');
  if (modal && sheet) {
    sheet.classList.add('translate-y-full');
    setTimeout(() => {
      modal.classList.add('opacity-0', 'pointer-events-none');
    }, 300);
  }
}

// Modal event listeners for Product Showcase
const btnCloseProductPreview = document.getElementById('btn-close-product-preview');
const productPreviewModal = document.getElementById('product-preview-modal');
const btnSelectPreviewProduct = document.getElementById('btn-select-preview-product');

if (btnCloseProductPreview) {
  btnCloseProductPreview.addEventListener('click', closeProductPreviewModal);
}

if (productPreviewModal) {
  productPreviewModal.addEventListener('click', (e) => {
    if (e.target === productPreviewModal) {
      closeProductPreviewModal();
    }
  });
}

if (btnSelectPreviewProduct) {
  btnSelectPreviewProduct.addEventListener('click', () => {
    if (!currentPreviewItem) return;
    const { category, key } = currentPreviewItem;
    if (category === 'tiers') state.tier = key;
    else if (category === 'religions') state.religion = key;
    else if (category === 'locations') state.wakeLocation = key;
    else if (category === 'durations') state.wakeDuration = key;
    else if (category === 'caskets') state.casket = key;
    else if (category === 'ashManagement') state.ashManagement = key;
    else if (category === 'addons') state.addons[key] = !state.addons[key];

    renderPlannerSelectors();
    recalculatePlannerPrice();
    closeProductPreviewModal();
  });
}

