function adminHeaders() {
  // No hardcoded fallback: the token comes from what the director typed at the
  // portal login, which must match SOLACE_ADMIN_TOKEN in the server's .env file.
  const token = state.adminToken || sessionStorage.getItem('solace_admin_token') || '';
  return {
    'X-Admin-Token': token
  };
}

