// Interactive Escalation Options Buttons inside chat
function appendEscalationButtons(parentBubble) {
  // Remove any existing escalation buttons in chatContainer to guarantee single appearance
  chatContainer.querySelectorAll('.escalation-buttons-container').forEach(el => el.remove());

  const container = document.createElement('div');
  container.className = 'escalation-buttons-container flex flex-wrap gap-2 mt-2 pt-1 border-t border-borderLight/40';

  const btnYes = document.createElement('button');
  btnYes.type = 'button';
  btnYes.className = 'px-3.5 py-1.5 rounded-xl bg-primary hover:bg-primaryHover text-white font-serif font-bold text-xs shadow-sm transition-all cursor-pointer';
  btnYes.textContent = tr('chip_speak_consultant');
  btnYes.addEventListener('click', () => {
    container.remove();
    openConsultantModal();
  });

  const btnNo = document.createElement('button');
  btnNo.type = 'button';
  btnNo.className = 'px-3 py-1.5 rounded-xl bg-fillColor hover:bg-highlight/30 text-textDark font-sans font-semibold text-xs border border-borderLight transition-all cursor-pointer';
  btnNo.textContent = 'Continue with AI';
  btnNo.addEventListener('click', () => {
    // Declining is a UI dismissal, not something to say to the assistant.
    // This used to send "Continue with AI" as a chat message, which the model
    // answered by re-explaining the same thing — and that answer mentioned a
    // consultant again, so the buttons reappeared, and the family could sit
    // there declining the same offer forever.
    container.remove();
    if (chatTextInput) chatTextInput.focus();
  });

  container.appendChild(btnYes);
  container.appendChild(btnNo);

  // Sit the buttons inside the bubble that made the offer, so the family sees
  // the way to accept right where the question was asked, rather than pinned to
  // the bottom of the feed away from its context.
  if (parentBubble) {
    parentBubble.appendChild(container);
  } else {
    chatContainer.appendChild(container);
  }
  scrollChatToBottom(true);
}

// Open / Close Consultant Modal
function openConsultantModal() {
  if (consultantModal) {
    if (state.user && state.user.name) {
      const nameInput = document.getElementById('consultant-form-name');
      if (nameInput) nameInput.value = state.user.name;
    }
    // The login field accepts a phone number OR an email, so route whatever
    // they typed into the matching field instead of always the phone box.
    if (state.user && state.user.contact) {
      const contact = String(state.user.contact).trim();
      const phoneInput = document.getElementById('consultant-form-phone');
      const emailInput = document.getElementById('consultant-form-email');
      const looksLikeEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact);

      if (looksLikeEmail) {
        if (emailInput && !emailInput.value) emailInput.value = contact;
      } else if (phoneInput && !phoneInput.value) {
        phoneInput.value = contact;
      }
    }
    consultantModal.classList.remove('opacity-0', 'pointer-events-none');
  }
}

function closeConsultantModal() {
  if (consultantModal) {
    consultantModal.classList.add('opacity-0', 'pointer-events-none');
  }
}

