// Submit Consultant Request Form
if (consultantRequestForm) {
  consultantRequestForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    const name = document.getElementById('consultant-form-name').value.trim();
    const phone = document.getElementById('consultant-form-phone').value.trim();
    const email = document.getElementById('consultant-form-email') ? document.getElementById('consultant-form-email').value.trim() : '';
    const reason = document.getElementById('consultant-form-reason').value.trim();

    try {
      const resp = await fetch(`${API_BASE}/api/consultant-requests`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          customer_name: name,
          phone: phone,
          email: email,
          preferred_contact_method: 'Phone / Chat',
          preferred_contact_time: 'Immediate',
          reason: reason,
          history: chatHistory,
          intake_state: state,
          user_id: (state.user && state.user.id) || null
        })
      });

      if (!resp.ok) throw new Error('Failed to submit request');
      const data = await resp.json();

      state.consultantRequestId = data.request_id;
      closeConsultantModal();

      // Show confirmation in chat
      appendBubble(`Your request for a Funeral Director has been logged (Ticket ID: ${data.request_id}). Our on-call director will reach out to you directly at ${phone}. You may also continue typing here.`, 'ai');
      chatHistory.push({ role: 'assistant', content: `Request logged (${data.request_id})` });

      // Start customer polling for live human handoff
      startCustomerPolling();

    } catch (err) {
      console.error('Error submitting consultant request:', err);
      alert('Could not submit request. Please ensure backend server is running.');
    }
  });
}

// Customer live polling loop for handoff
function startCustomerPolling() {
  if (state.customerPollTimer) clearInterval(state.customerPollTimer);
  state.customerPollTimer = setInterval(pollCustomerChat, 2000);
}

async function pollCustomerChat() {
  if (!state.consultantRequestId) return;
  try {
    const resp = await fetch(`${API_BASE}/api/consultant-requests/${state.consultantRequestId}`);
    if (!resp.ok) return;
    const ticket = await resp.json();

    state.conversationMode = ticket.mode;

    // Reflect the handoff in the chip row: no point offering an escalation
    // to someone already speaking with a consultant.
    renderQuickChips();

    const banner = document.getElementById('human-mode-banner');
    if (ticket.mode === 'HUMAN') {
      if (banner) {
        banner.classList.remove('hidden');
        const staffName = document.getElementById('human-consultant-name');
        if (staffName) staffName.textContent = `Staff: ${ticket.assigned_staff || 'Marcus Chen'}`;
      }
      // The moment a person takes over is a real event in the conversation, so
      // it gets a rule across the feed rather than only a banner at the top.
      // Scrolling back, the family can see exactly where the machine stopped
      // answering and someone started.
      appendHandoffRule(ticket.assigned_staff || 'Marcus Chen', 'joined');
    } else if (ticket.mode === 'CLOSED') {
      appendHandoffRule(ticket.assigned_staff || 'Marcus Chen', 'ended');
      if (banner) banner.classList.add('hidden');
      if (state.customerPollTimer) clearInterval(state.customerPollTimer);
    }

    // Sync messages feed if staff has sent new messages
    if (ticket.conversation && ticket.conversation.length > 0) {
      const historyContents = chatHistory.map(h => h.content);
      ticket.conversation.forEach(m => {
        if (m.role === 'staff' && !historyContents.includes(m.content)) {
          if (m.sender === 'System') {
            // The ruled handoff line already announces the takeover, so the
            // grey system sentence saying the same thing is duplication.
            const isTakeoverNotice = /has joined the chat|taken over from/i.test(m.content);
            if (!isTakeoverNotice) {
              // Strip any leading emoji the backend prefixed onto the notice.
              appendSystemLine(m.content.replace(/^[^\w]+/, ''));
            }
          } else {
            appendBubble(m.content, 'staff', m.sender);
          }
          chatHistory.push({ role: 'assistant', content: m.content });
        }
      });
    }

  } catch (err) {
    console.error('Error polling customer chat:', err);
  }
}

