// ============================================================
// DIRECTOR DESKTOP ALERTS
// Uses the browser Notification API so a new escalation reaches the
// director even when the console is behind another window. Falls back
// to an in-console toast when notifications are unavailable or denied,
// so the director is never silently left unaware.
// ============================================================

// id -> number of messages we have already seen for that ticket
const seenTicketMessageCounts = new Map();
let consoleListPollTimer = null;
let hasSeededTicketBaseline = false;

function desktopAlertsSupported() {
  return typeof window !== 'undefined' && 'Notification' in window;
}

function updateAlertsButton() {
  const btn = document.getElementById('btn-enable-alerts');
  const state = document.getElementById('alerts-state');
  if (!btn || !state) return;

  btn.classList.remove('is-on', 'is-blocked');

  if (!desktopAlertsSupported()) {
    state.textContent = 'Unavailable';
    btn.disabled = true;
    return;
  }

  if (Notification.permission === 'granted') {
    state.textContent = desktopAlertsOn ? 'On' : 'Off';
    btn.classList.toggle('is-on', desktopAlertsOn);
  } else if (Notification.permission === 'denied') {
    state.textContent = 'Blocked';
    btn.classList.add('is-blocked');
  } else {
    state.textContent = 'Off';
  }
}

// Must be called from a user gesture (the sign-in click), or Chrome ignores it.
function requestDesktopAlertPermission() {
  if (!desktopAlertsSupported()) {
    updateAlertsButton();
    return;
  }
  if (Notification.permission === 'default') {
    Notification.requestPermission().then(updateAlertsButton).catch(() => updateAlertsButton());
  } else {
    updateAlertsButton();
  }
}

// ============================================================
// ESCALATION CHIME
// A soft two-note tone synthesised with the Web Audio API, so there is
// no audio file to ship. Off by default: browsers block audio until the
// page has been interacted with, and an unannounced sound in a quiet
// room is worse than none.
// ============================================================

let escalationSoundOn = false;

// A page cannot revoke its own notification permission — only the browser
// settings can. So the menu toggles this app-level switch instead, letting
// the director silence banners without touching Chrome's settings.
let desktopAlertsOn = true;
let audioCtx = null;

function ensureAudioContext() {
  if (!audioCtx) {
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return null;
    audioCtx = new Ctx();
  }
  // Browsers start the context suspended until a user gesture resumes it.
  if (audioCtx.state === 'suspended') audioCtx.resume();
  return audioCtx;
}

// One note of the chime. Gain ramps rather than switching on and off,
// because an abrupt start or stop produces an audible click.
function playTone(ctx, frequency, startAt, duration, peakGain) {
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();

  osc.type = 'sine';
  osc.frequency.value = frequency;

  gain.gain.setValueAtTime(0.0001, startAt);
  gain.gain.exponentialRampToValueAtTime(peakGain, startAt + 0.04);
  gain.gain.exponentialRampToValueAtTime(0.0001, startAt + duration);

  osc.connect(gain);
  gain.connect(ctx.destination);
  osc.start(startAt);
  osc.stop(startAt + duration + 0.02);
}

function playEscalationChime() {
  if (!escalationSoundOn) return;
  const ctx = ensureAudioContext();
  if (!ctx) return;

  try {
    // Rising perfect fourth (E5 -> A5): warm and short, not an alarm.
    const now = ctx.currentTime;
    playTone(ctx, 659.25, now, 0.28, 0.13);
    playTone(ctx, 880.00, now + 0.16, 0.42, 0.11);
  } catch (err) {
    console.error('Chime failed:', err);
  }
}

function updateSoundButton() {
  const btn = document.getElementById('btn-toggle-sound');
  const state = document.getElementById('sound-state');
  if (!btn || !state) return;
  state.textContent = escalationSoundOn ? 'On' : 'Off';
  btn.classList.toggle('is-on', escalationSoundOn);
  btn.setAttribute('aria-pressed', String(escalationSoundOn));
}

function toggleEscalationSound() {
  escalationSoundOn = !escalationSoundOn;
  updateSoundButton();
  // Play once on enabling, both to confirm the setting and to unlock
  // audio while we are inside the click that the browser requires.
  if (escalationSoundOn) playEscalationChime();
}

function showConsoleToast(title, body) {
  const stack = document.getElementById('console-toast-stack');
  if (!stack) return;

  const toast = document.createElement('div');
  toast.className = 'console-toast';
  toast.innerHTML = `<div class="console-toast-title">${escapeHtml(title)}</div>
    <div class="console-toast-body">${escapeHtml(body)}</div>`;
  stack.appendChild(toast);

  // Fade out, then remove, so the stack does not grow unbounded.
  setTimeout(() => toast.classList.add('is-leaving'), 6000);
  setTimeout(() => toast.remove(), 6600);
}

function notifyDirector(title, body, requestId) {
  // Desktop notification when we are allowed one.
  if (desktopAlertsOn && desktopAlertsSupported() && Notification.permission === 'granted') {
    try {
      const note = new Notification(title, {
        body: body,
        icon: 'logo.png',
        badge: 'logo.png',
        tag: requestId || 'solace-escalation',
        renotify: false
      });
      note.onclick = () => {
        window.focus();
        note.close();
        if (requestId) openStaffChatModal(requestId);
      };
    } catch (err) {
      console.error('Desktop notification failed:', err);
      showConsoleToast(title, body);
      return;
    }
  }

  // Always show the in-console toast as well: if the director is looking
  // at the console, the desktop notification may be suppressed by the OS.
  showConsoleToast(title, body);
  playEscalationChime();
}

// Compare the freshly fetched ticket list against what we saw last poll
// and raise an alert for anything genuinely new.
function detectNewActivity(requests) {
  if (!Array.isArray(requests)) return;

  // First load after sign-in seeds the baseline silently, otherwise the
  // director gets a burst of alerts for tickets that were already there.
  if (!hasSeededTicketBaseline) {
    requests.forEach(req => {
      seenTicketMessageCounts.set(req.request_id, (req.conversation || []).length);
    });
    hasSeededTicketBaseline = true;
    return;
  }

  requests.forEach(req => {
    const msgCount = (req.conversation || []).length;

    if (!seenTicketMessageCounts.has(req.request_id)) {
      notifyDirector(
        `New request from ${req.customer_name}`,
        req.ai_summary || req.reason || 'A family has requested a consultant.',
        req.request_id
      );
      seenTicketMessageCounts.set(req.request_id, msgCount);
      return;
    }

    const previous = seenTicketMessageCounts.get(req.request_id);
    if (msgCount > previous) {
      // Only alert on messages from the family, not our own replies
      // echoing back from the server.
      const latest = (req.conversation || [])[msgCount - 1] || {};
      if (latest.role === 'user') {
        notifyDirector(
          `${req.customer_name} replied`,
          latest.content || 'New message on an open consultation.',
          req.request_id
        );
      }
      seenTicketMessageCounts.set(req.request_id, msgCount);
    }
  });
}

function startConsoleListPolling() {
  if (consoleListPollTimer) clearInterval(consoleListPollTimer);
  consoleListPollTimer = setInterval(loadStaffDashboardData, 5000);

  // Separate, faster tick purely for the "x seconds ago" label, so it counts
  // up smoothly between the five-second data fetches.
  if (consoleClockTimer) clearInterval(consoleClockTimer);
  consoleClockTimer = setInterval(renderConsoleFreshness, 1000);
}

function stopConsoleListPolling() {
  if (consoleListPollTimer) clearInterval(consoleListPollTimer);
  consoleListPollTimer = null;
  if (consoleClockTimer) clearInterval(consoleClockTimer);
  consoleClockTimer = null;
  lastConsoleSyncAt = null;
}

async function performAdminLogin(id, pass) {
  // Previously this only checked that both fields were non-empty, which meant
  // any two characters opened the console. The token is now verified against
  // the server, which compares it to SOLACE_ADMIN_TOKEN from .env. The
  // dashboard opens only if that call succeeds.
  const showAdminError = (msg) => {
    if (!adminLoginError) return;
    // Write into the inner span so the warning icon beside it is preserved.
    const slot = adminLoginError.querySelector('span') || adminLoginError;
    slot.textContent = msg;
    adminLoginError.classList.remove('hidden');
  };

  if (!id || !pass) {
    showAdminError('Please enter both a Staff ID and the admin token.');
    return;
  }

  if (adminLoginError) adminLoginError.classList.add('hidden');

  try {
    const resp = await fetch(`${API_BASE}/api/admin/events`, {
      headers: { 'X-Admin-Token': pass }
    });

    if (!resp.ok) {
      showAdminError(resp.status === 503
        ? 'Server has no admin token configured. Set SOLACE_ADMIN_TOKEN in .env.'
        : 'Invalid admin token. Check SOLACE_ADMIN_TOKEN in your .env file.');
      return;
    }
  } catch (err) {
    showAdminError('Cannot reach the server. Is uvicorn running?');
    return;
  }

  state.isAdminLoggedIn = true;
  state.adminToken = pass;
  sessionStorage.setItem('solace_admin_token', state.adminToken);
  closeAdminLoginModal();
  // Asked here because this runs inside the sign-in click, which is the
  // user gesture browsers require before prompting for notifications.
  requestDesktopAlertPermission();
  showAdminLoadingGate();

  // Hold executive loading gate for smooth visual authentication transition
  setTimeout(() => {
    openStaffDashboardInternal();
    setTimeout(() => {
      hideAdminLoadingGate();
    }, 350);
  }, ADMIN_LOADING_MS);
}

function handleAdminLogout() {
  state.isAdminLoggedIn = false;
  state.adminToken = null;
  sessionStorage.removeItem('solace_admin_token');
  if (typeof closeSecureDocOverlay === 'function') closeSecureDocOverlay();
  hideAdminLoadingGate();
  if (staffDashboardModal) staffDashboardModal.classList.add('opacity-0', 'pointer-events-none');
  if (staffChatModal) staffChatModal.classList.add('opacity-0', 'pointer-events-none');
  if (state.staffPollTimer) clearInterval(state.staffPollTimer);
  stopConsoleListPolling();
  openAdminLoginModal();
}

