// Settings dropdown in the console header. Kept as a plain toggle with an
// outside-click and Escape close, rather than a library popover.
const btnConsoleSettings = document.getElementById('btn-console-settings');
const consoleSettingsMenu = document.getElementById('console-settings-menu');

function setConsoleSettingsOpen(open) {
  if (!btnConsoleSettings || !consoleSettingsMenu) return;
  consoleSettingsMenu.classList.toggle('is-open', open);
  btnConsoleSettings.classList.toggle('is-open', open);
  btnConsoleSettings.setAttribute('aria-expanded', String(open));
}

if (btnConsoleSettings && consoleSettingsMenu) {
  btnConsoleSettings.addEventListener('click', (e) => {
    e.stopPropagation();
    setConsoleSettingsOpen(!consoleSettingsMenu.classList.contains('is-open'));
  });

  // Clicks inside the menu toggle settings; they must not close it.
  consoleSettingsMenu.addEventListener('click', (e) => e.stopPropagation());

  document.addEventListener('click', () => setConsoleSettingsOpen(false));
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') setConsoleSettingsOpen(false);
  });
}

