if (btnEnableAlerts) {
  btnEnableAlerts.addEventListener('click', () => {
    if (!desktopAlertsSupported()) return;

    if (Notification.permission === 'denied') {
      showConsoleToast(
        'Alerts are blocked',
        'Chrome is blocking notifications for this page. Allow them from the padlock icon in the address bar, then reload.'
      );
      return;
    }

    // Already permitted: the row becomes a plain on/off switch.
    if (Notification.permission === 'granted') {
      desktopAlertsOn = !desktopAlertsOn;
      updateAlertsButton();
      return;
    }

    // Not asked yet: prompt, and switch on if the director allows.
    desktopAlertsOn = true;
    requestDesktopAlertPermission();
  });
}

