let consoleHealthPollTimer = null;
let consoleHealthClockTimer = null;
let lastHealthSyncAt = null;
let currentConsoleView = 'escalations';

function startConsoleHealthPolling() {
  if (consoleHealthPollTimer) clearInterval(consoleHealthPollTimer);
  consoleHealthPollTimer = setInterval(() => {
    loadHealthDashboardData();
    loadSafetyEvents();
  }, 10000); // 10-second polling interval while health view is active

  if (consoleHealthClockTimer) clearInterval(consoleHealthClockTimer);
  consoleHealthClockTimer = setInterval(renderHealthFreshness, 1000);
}

function stopConsoleHealthPolling() {
  if (consoleHealthPollTimer) clearInterval(consoleHealthPollTimer);
  consoleHealthPollTimer = null;
  if (consoleHealthClockTimer) clearInterval(consoleHealthClockTimer);
  consoleHealthClockTimer = null;
  lastHealthSyncAt = null;
}

function renderHealthFreshness() {
  const label = document.getElementById('console-health-last-sync');
  if (!label) return;

  if (!lastHealthSyncAt) {
    label.textContent = 'connecting';
    return;
  }

  const seconds = Math.floor((Date.now() - lastHealthSyncAt) / 1000);
  label.textContent = seconds < 5 ? 'just now' : `${seconds}s ago`;

  const dot = document.getElementById('console-health-live-dot');
  if (dot) dot.classList.toggle('is-stale', seconds > 30);
}

function setConsoleView(view) {
  currentConsoleView = view || 'escalations';

  const viewTabs = document.querySelectorAll('#console-view-tabs .console-view-tab');
  viewTabs.forEach(tab => {
    const tabView = tab.getAttribute('data-view');
    if (tabView === currentConsoleView) {
      tab.className = 'console-view-tab active px-3 py-1 rounded text-[11.5px] font-semibold bg-copper/25 text-copperSoft border border-copper/40 transition-all cursor-pointer';
    } else {
      tab.className = 'console-view-tab px-3 py-1 rounded text-[11.5px] font-semibold text-creamMuted hover:text-cream transition-all cursor-pointer';
    }
  });

  const escalationsView = document.getElementById('console-escalations-view');
  const healthView = document.getElementById('console-health-view');

  if (currentConsoleView === 'health') {
    if (escalationsView) escalationsView.classList.add('hidden');
    if (healthView) healthView.classList.remove('hidden');

    stopConsoleListPolling();
    startConsoleHealthPolling();
    loadHealthDashboardData();
    loadSafetyEvents();
  } else {
    if (escalationsView) escalationsView.classList.remove('hidden');
    if (healthView) healthView.classList.add('hidden');

    stopConsoleHealthPolling();
    startConsoleListPolling();
    loadStaffDashboardData();
  }
}

// View switcher event listeners
const consoleViewTabs = document.querySelectorAll('#console-view-tabs .console-view-tab');
consoleViewTabs.forEach(tab => {
  tab.addEventListener('click', () => {
    const view = tab.getAttribute('data-view');
    setConsoleView(view);
  });
});

async function loadHealthDashboardData() {
  const errorBanner = document.getElementById('console-health-error');
  try {
    const res = await fetch(STATUS_URL);
    if (!res.ok) throw new Error('Status API response not ok');
    const data = await res.json();

    if (errorBanner) errorBanner.classList.add('hidden');

    lastHealthSyncAt = Date.now();
    renderHealthFreshness();

    // Outage survival banner
    const survivesBadge = document.getElementById('health-survives-badge');
    const survivesText = document.getElementById('health-survives-text');
    if (survivesBadge && survivesText) {
      if (data.survives_ollama_outage) {
        survivesBadge.className = 'inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full text-[11px] font-semibold bg-sage/15 text-sage border border-sage/40 transition-colors';
        survivesText.textContent = 'Zero-dependency mode active · Survives Ollama outage';
      } else {
        survivesBadge.className = 'inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full text-[11px] font-semibold bg-brass/15 text-brass border border-brass/40 transition-colors';
        survivesText.textContent = 'Ollama-dependent';
      }
    }

    // Tile 1: Generation Model
    const genDot = document.getElementById('health-gen-dot');
    const genModel = document.getElementById('health-gen-model');
    const genSub = document.getElementById('health-gen-sub');
    if (data.online) {
      if (genDot) genDot.className = 'w-1.5 h-1.5 rounded-full bg-sage';
      if (genModel) genModel.textContent = data.model || 'Connected';
      if (genSub) genSub.textContent = data.detail || 'Local Ollama instance';
    } else {
      if (genDot) genDot.className = 'w-1.5 h-1.5 rounded-full bg-ember';
      if (genModel) genModel.textContent = 'Unreachable';
      if (genSub) genSub.textContent = 'Fallback ladder active';
    }

    // Tile 2: Embeddings Subsystem
    const embedDot = document.getElementById('health-embed-dot');
    const embedModel = document.getElementById('health-embed-model');
    const embedSub = document.getElementById('health-embed-sub');
    const sr = data.semantic_routing || {};
    if (sr.ready) {
      if (embedDot) embedDot.className = 'w-1.5 h-1.5 rounded-full bg-sage';
      const provName = sr.provider ? (sr.provider.charAt(0).toUpperCase() + sr.provider.slice(1)) : 'FastEmbed';
      if (embedModel) embedModel.textContent = provName;
      if (embedSub) embedSub.textContent = `${sr.model || 'BAAI/bge-small-en-v1.5'} (${sr.dimension || 384}d)`;
    } else {
      if (embedDot) embedDot.className = 'w-1.5 h-1.5 rounded-full bg-ember';
      if (embedModel) embedModel.textContent = 'Unavailable';
      if (embedSub) embedSub.textContent = 'Fuzzy keyword floor only';
    }

    // Tile 3: Indexed Knowledge Base
    const answersCount = document.getElementById('health-answers-count');
    const answersSub = document.getElementById('health-answers-sub');
    const ai = data.answer_index || {};
    if (answersCount) answersCount.textContent = ai.indexed_entries || 0;
    if (answersSub) answersSub.textContent = '100 faq · 49 blog entries';

    // Tile 4: Guardrail Anchors
    const anchorsCount = document.getElementById('health-anchors-count');
    const anchorsSub = document.getElementById('health-anchors-sub');
    if (anchorsCount) anchorsCount.textContent = sr.total_anchors || 35;
    if (anchorsSub) anchorsSub.textContent = '7 intent routes';

  } catch (err) {
    console.error('Health fetch error:', err);
    if (errorBanner) errorBanner.classList.remove('hidden');

    const genDot = document.getElementById('health-gen-dot');
    const genModel = document.getElementById('health-gen-model');
    const genSub = document.getElementById('health-gen-sub');
    if (genDot) genDot.className = 'w-1.5 h-1.5 rounded-full bg-ember';
    if (genModel) genModel.textContent = 'Unreachable';
    if (genSub) genSub.textContent = 'Fallback ladder active';
  }
}

async function loadSafetyEvents() {
  const listContainer = document.getElementById('safety-events-list');
  if (!listContainer) return;

  try {
    const res = await fetch(`${API_BASE}/api/admin/events?limit=50`, {
      headers: adminHeaders()
    });
    if (!res.ok) throw new Error('Safety events fetch failed');
    const data = await res.json();
    const events = data.events || [];

    if (events.length === 0) {
      listContainer.innerHTML = `
        <div class="py-8 text-center text-xs text-creamMuted/60 font-medium">
          No safety or guardrail events recorded yet.
        </div>
      `;
      return;
    }

    listContainer.innerHTML = events.map(e => {
      let badgeHtml = '';
      if (e.kind === 'crisis') {
        badgeHtml = `<span class="px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider bg-ember/20 text-ember border border-ember/30 shrink-0">Crisis (${e.score || 0}/${e.threshold || 70})</span>`;
      } else if (e.kind === 'crisis_near_miss') {
        badgeHtml = `<span class="px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider bg-brass/20 text-brass border border-brass/30 shrink-0">Near-miss (${e.score || 0}/${e.threshold || 70})</span>`;
      } else if (e.kind === 'pdpa') {
        badgeHtml = `<span class="px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider bg-copper/20 text-copper border border-copper/30 shrink-0">PDPA</span>`;
      } else if (e.kind === 'prompt_attack') {
        badgeHtml = `<span class="px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider bg-ember/20 text-ember border border-ember/30 shrink-0">Attack</span>`;
      } else if (e.kind === 'document_upload') {
        badgeHtml = `<span class="px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider bg-emerald-500/20 text-emerald-300 border border-emerald-500/30 shrink-0">Document</span>`;
      } else {
        badgeHtml = `<span class="px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider bg-creamMuted/20 text-creamMuted border border-creamMuted/30 shrink-0">Handoff</span>`;
      }

      let timeStr = e.ts;
      try {
        const dt = new Date(e.ts);
        timeStr = dt.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      } catch (_) {}

      return `
        <div class="p-3 bg-nightPanel/90 border border-nightLine/60 rounded-xl flex items-center justify-between gap-4">
          <div class="flex items-center gap-3 min-w-0 flex-1">
            ${badgeHtml}
            <span class="text-xs text-cream/90 font-medium truncate" title="${escapeHtml(e.detail)}">${escapeHtml(e.detail)}</span>
          </div>
          <span class="text-[11px] text-creamMuted/70 tabular-nums shrink-0 font-mono">${timeStr}</span>
        </div>
      `;
    }).join('');

  } catch (err) {
    console.error('Failed to load safety events:', err);
  }
}

function initRouteProbe() {
  const probeForm = document.getElementById('route-probe-form');
  const probeInput = document.getElementById('route-probe-input');
  const probeError = document.getElementById('route-probe-error');
  const probeResults = document.getElementById('route-probe-results');
  const probeRows = document.getElementById('route-probe-rows');
  const probeGates = document.getElementById('route-probe-gates');

  if (probeInput && probeError) {
    probeInput.addEventListener('input', () => {
      probeError.classList.add('hidden');
    });
  }

  if (probeForm) {
    probeForm.addEventListener('submit', async (e) => {
      e.preventDefault();
      const text = (probeInput ? probeInput.value : '').trim();
      if (!text) {
        if (probeError) probeError.classList.remove('hidden');
        return;
      }

      if (probeError) probeError.classList.add('hidden');

      const btn = document.getElementById('btn-route-probe');
      if (btn) btn.innerHTML = '<span>Scoring...</span>';

      try {
        const res = await fetch(`${API_BASE}/api/admin/route-probe`, {
          method: 'POST',
          headers: {
            ...adminHeaders(),
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({ message: text })
        });

        if (btn) btn.innerHTML = '<span>Score</span>';

        if (!res.ok) throw new Error('Route probe API failed');
        const data = await res.json();

        if (probeResults) probeResults.classList.remove('hidden');

        if (probeRows && Array.isArray(data.routes)) {
          probeRows.innerHTML = data.routes.map(r => {
            const scorePct = Math.min(Math.max(r.score * 100, 0), 100);
            const threshPct = Math.min(Math.max(r.threshold * 100, 0), 100);
            const isMatched = r.matched;

            return `
              <div class="flex items-center gap-4 py-1">
                <!-- Route Name -->
                <div class="w-36 text-[11px] font-semibold ${isMatched ? 'text-cream font-bold' : 'text-creamMuted'} uppercase tracking-wider truncate" title="${r.route}">
                  ${escapeHtml(r.route.replace('_', ' '))}
                </div>

                <!-- Score Track & Threshold Tick -->
                <div class="relative flex-1 h-2.5 bg-nightLine rounded-full overflow-visible flex items-center">
                  <!-- Fill bar -->
                  <div class="h-full rounded-full transition-all duration-300 ${isMatched ? 'bg-sage' : 'bg-creamMuted/40'}"
                    style="width: ${scorePct}%;"></div>
                  <!-- 1px Threshold Tick -->
                  <div class="absolute top-[-3px] bottom-[-3px] w-[2px] bg-cream/80 z-10 pointer-events-none"
                    style="left: ${threshPct}%;"
                    title="Threshold: ${(r.threshold).toFixed(2)}"></div>
                </div>

                <!-- Numeric Score -->
                <div class="w-16 text-right tabular-nums text-xs font-bold ${isMatched ? 'text-sage' : 'text-creamMuted'}">
                  ${(r.score).toFixed(2)}
                </div>
              </div>
            `;
          }).join('');
        }

        if (probeGates) {
          probeGates.innerHTML = `
            <div class="flex items-center gap-3">
              <span class="text-creamMuted font-semibold text-[11px]">Rule triggers:</span>
              <span class="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md text-[10px] font-semibold ${data.keyword_hit ? 'bg-copper/20 text-copper border border-copper/40' : 'bg-nightLine/50 text-creamMuted/60 border border-nightLine'}">
                <span class="w-1.5 h-1.5 rounded-full ${data.keyword_hit ? 'bg-copper' : 'bg-creamMuted/40'}"></span>
                ${data.keyword_hit ? 'Keyword gate fired' : 'Keyword gate inactive'}
              </span>
              <span class="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md text-[10px] font-semibold ${data.fuzzy_hit ? 'bg-copper/20 text-copper border border-copper/40' : 'bg-nightLine/50 text-creamMuted/60 border border-nightLine'}">
                <span class="w-1.5 h-1.5 rounded-full ${data.fuzzy_hit ? 'bg-copper' : 'bg-creamMuted/40'}"></span>
                ${data.fuzzy_hit ? 'Fuzzy typo gate fired' : 'Fuzzy typo gate inactive'}
              </span>
            </div>
          `;
        }

      } catch (err) {
        if (btn) btn.innerHTML = '<span>Score</span>';
        console.error('Route probe request error:', err);
      }
    });
  }
}

